INSERT INTO public.recipes (id, name, source_cuisine, cuisine, diet, is_jain, dish_type, serves, prep_time, cook_time, blurb, tip, badge, tags, ingredients, method, meal_hint, serving_unit, serving_weight_g, kcal, protein_g, carbs_g, fat_g, fibre_g, iron_mg, calcium_mg, vit_b12_mcg, sodium_mg, nutrition_estimated) VALUES
  (183, 'String Hoppers (Idiyappam) with Coconut Gravy', 'Sri Lankan', 'asian', 'vegan', false, 'main', '2', '15 min', '15 min', 'Steamed rice flour noodle nests served with a silky, mildly spiced coconut milk gravy — the lighter, more delicate cousin of the hopper.', 'Work the dough while warm — as it cools it becomes stiff and will not press through the mould smoothly.', 'Traditional', NULL, ARRAY['1.5 cups rice flour','1.5 cups boiling water','Salt to taste','For coconut gravy: 1 cup thin coconut milk, 1/2 cup thick coconut milk, 1 onion, 1 green chilli, curry leaves, mustard seeds']::text[], ARRAY['Pour boiling water over rice flour with salt; mix to a pliable dough.','Press dough through a string hopper press onto steaming discs; steam 5-8 min until cooked.','Saute onion, chilli and curry leaves; add thin coconut milk and simmer 5 min.','Stir in thick coconut milk; heat gently without boiling; season.','Serve string hopper nests with warm coconut gravy poured over.']::text[], ARRAY['breakfast']::text[], 'serving', 200, 250, 4.2, 38.5, 7.8, 1.2, 1.8, 42, 0, 320, false),
  (184, 'Kiribath (Milk Rice)', 'Sri Lankan', 'asian', 'vegan', true, 'main', '3', '5 min', '25 min', 'Thick, creamy rice cooked in coconut milk until each grain is enveloped in richness — a Sri Lankan celebration dish eaten at every auspicious occasion.', 'Kiribath thickens as it cools, so remove from heat while it looks slightly looser than desired — it will set perfectly in the tray.', 'Traditional', NULL, ARRAY['1 cup short-grain rice, rinsed','1.5 cups coconut milk','1 cup water','Salt to taste','Coconut sambol or jaggery to serve']::text[], ARRAY['Bring water and rice to a boil; cook 10 min until water absorbs.','Add coconut milk and salt; stir and cook on very low heat 15 min, stirring occasionally.','Rice should be thick and creamy with no liquid pooling.','Pour into a greased tray and press flat; cool slightly.','Cut into diamond shapes; serve with sambol for savoury or jaggery for sweet.']::text[], ARRAY['breakfast']::text[], 'serving', 200, 310, 4.2, 42.5, 10.8, 0.8, 0.6, 32, 0, 180, false),
  (185, 'Roti with Coconut Sambol', 'Sri Lankan', 'asian', 'vegan', false, 'staple', '2', '15 min', '20 min', 'Soft, griddle-cooked coconut flatbreads alongside a punchy, fresh coconut and chilli relish — a Sri Lankan morning ritual.', 'Desiccated coconut in the dough gives the roti a characteristic texture and subtle sweetness distinct from plain flatbread.', 'Traditional', NULL, ARRAY['2 cups flour','1/2 cup desiccated coconut','1/2 cup water','1/2 tsp salt','1 tbsp oil','Sambol: 1 cup fresh grated coconut, 3 dried red chillies, 1/2 onion, lime, salt']::text[], ARRAY['Mix flour, coconut, salt and oil; add water gradually to form a soft, pliable dough.','Rest 10 min; divide and roll each portion into a thin circle.','Cook on a dry hot griddle 2 min each side until lightly charred.','For sambol: blend chillies and onion to a paste; mix into coconut with salt and lime juice.','Serve warm roti with sambol alongside.']::text[], ARRAY['breakfast']::text[], 'piece', 120, 290, 8.5, 38.2, 10.8, 3.2, 2.1, 85, 0, 420, false),
  (186, 'Pittu with Coconut Milk', 'Sri Lankan', 'asian', 'vegan', true, 'main', '2', '10 min', '20 min', 'A steamed cylinder of rice flour and coconut that crumbles into the mouth — served with warm coconut milk and a drizzle of sweetened condensed milk for a truly Sri Lankan morning.', 'The mixture should feel like damp sand — too wet and it becomes gummy; too dry and it will not steam into a cohesive cylinder.', 'Traditional', NULL, ARRAY['1 cup rice flour (roasted)','3/4 cup fresh grated coconut','Water to bind (a few tbsp)','Salt to taste','1 cup warm coconut milk to serve','1 tbsp sweetened condensed milk (optional)','Banana leaf strips or bamboo pittu mould']::text[], ARRAY['Mix rice flour, coconut and salt; add water tablespoon by tablespoon until the mixture holds when squeezed but crumbles when released.','Fill a bamboo pittu steamer in alternating layers of mixture and coconut.','Steam over boiling water for 10-12 min.','Turn out onto a plate; the cylinder should hold its shape.','Serve with warm coconut milk poured over and condensed milk drizzled on top.']::text[], ARRAY['breakfast']::text[], 'serving', 200, 260, 4.2, 32.5, 9.8, 2.1, 1.8, 78, 0.05, 185, false),
  (187, 'Sri Lankan Rice and Curry Plate', 'Sri Lankan', 'asian', 'vegan', false, 'main', '2', '15 min', '40 min', 'A full Sri Lankan lunch plate — mounds of rice surrounded by three or four curries, a sambola and a pickle — a complete meal in one glorious spread.', 'The genius of a Sri Lankan rice and curry plate is balance — make sure at least one component is cooling (coconut) to offset the heat.', 'Traditional', NULL, ARRAY['2 cups steamed white rice','1 portion Sri Lankan Dal Curry','1 portion vegetable curry (potato or beans)','Coconut sambol','Papadom','Pickle (lime or raw mango)','Green chilli for garnish']::text[], ARRAY['Steam rice; make dal curry by simmering red lentils with coconut milk, turmeric and tempered mustard seeds.','Prepare a simple potato curry with curry powder, coconut milk and curry leaves.','Arrange rice on a banana leaf or plate; surround with small portions of each curry.','Place sambol and pickle on the side.','Serve with papadoms and encourage eating with the right hand in the traditional style.']::text[], ARRAY['lunch']::text[], 'plate', 400, 520, 12.5, 68, 16.5, 5.2, 2.8, 95, 0.3, 685, false),
  (188, 'Dhal Curry with Rice (Sri Lankan)', 'Sri Lankan', 'asian', 'vegan', false, 'main', '2', '5 min', '25 min', 'Sri Lanka''s most comforting everyday dish — silky red lentils simmered with coconut milk, green chilli and curry leaves.', 'Sri Lankan dal is meant to be softer and creamier than Indian dal — do not stop cooking at the al dente stage.', 'Traditional', NULL, ARRAY['1 cup red lentils, rinsed','1 cup coconut milk','1 cup water','1 green chilli, slit','1/2 tsp turmeric','1 tsp cumin seeds','8 curry leaves','1 onion, sliced','1 tsp mustard seeds','Salt to taste','Steamed rice to serve']::text[], ARRAY['Cook lentils with water, turmeric and green chilli until soft and breaking down.','Add coconut milk; stir and simmer 5 min; season with salt.','Heat oil; splutter mustard seeds and cumin; add onion and curry leaves; fry until golden.','Pour tempering over dal; stir gently.','Serve over steamed rice.']::text[], ARRAY['lunch']::text[], 'plate', 300, 380, 14.2, 48.5, 9.8, 8.2, 4.1, 52, 0, 420, false),
  (189, 'Gotukola Sambol with Rice', 'Sri Lankan', 'asian', 'vegan', false, 'main', '2', '15 min', '20 min', 'Steamed rice served with a fresh, raw coconut and gotukola (pennywort) salad — a uniquely Sri Lankan herb-forward accompaniment.', 'Gotukola sambol is best eaten fresh and raw — do not dress it ahead of time as the lime wilts the leaves quickly.', 'Traditional', NULL, ARRAY['2 cups steamed white rice','2 cups gotukola (pennywort) or watercress, finely chopped','1/2 cup fresh grated coconut','1/2 onion, very finely diced','2 green chillies, minced','Juice of 1 lime','Salt to taste','Pappadom to serve']::text[], ARRAY['Cook rice until fluffy.','Combine gotukola with coconut, onion and green chilli.','Add lime juice and salt; toss and taste — it should be sharp, fresh and slightly spicy.','Serve a generous mound of sambol alongside hot rice.','Add a pappadom for crunch.']::text[], ARRAY['lunch']::text[], 'plate', 300, 310, 6.2, 48.5, 6.8, 2.1, 1.8, 85, 0, 320, false),
  (190, 'Tempered Lentil Rice', 'Sri Lankan', 'asian', 'vegan', false, 'main', '2', '10 min', '30 min', 'Rice cooked with lentils and tempered with mustard, curry leaves and crispy onion — a Sri Lankan one-pot that is more than the sum of its parts.', 'The tempering should be smoking hot when it hits the rice — the sizzle and fragrance is the signature of this dish.', 'Traditional', NULL, ARRAY['1 cup basmati rice','1/2 cup red lentils','3 cups water','1 tsp mustard seeds','1 tsp cumin seeds','10 curry leaves','1 onion, finely sliced','1/2 tsp turmeric','2 dried red chillies','Coconut oil and salt']::text[], ARRAY['Rinse rice and lentils together; bring to a boil in salted water with turmeric.','Simmer 20 min until both are cooked and water absorbed.','Heat coconut oil until very hot; splutter mustard seeds, cumin and dried chillies.','Add onion and curry leaves; fry until onion is deeply golden and crisp.','Pour sizzling tempering over rice; fold gently and serve.']::text[], ARRAY['lunch']::text[], 'plate', 300, 360, 12.5, 52.3, 8.2, 5.1, 4.8, 45, 0, 320, false),
  (191, 'Jackfruit Curry with Rice', 'Sri Lankan', 'asian', 'vegan', false, 'main', '3', '15 min', '35 min', 'Young jackfruit simmered in a coconut milk and Sri Lankan spice gravy until tender and flavourful — a meaty, satisfying curry.', 'Canned young green jackfruit works perfectly here — rinse thoroughly to remove the brine before adding to the curry.', 'Traditional', NULL, ARRAY['400g young green jackfruit (canned or fresh)','1 can coconut milk','1 onion, sliced','3 garlic cloves, minced','1 tsp Sri Lankan curry powder','1/2 tsp turmeric','8 curry leaves','1 lemongrass stalk, bruised','Salt to taste','Steamed rice to serve']::text[], ARRAY['If using fresh jackfruit, boil in salted water 20 min until tender; drain.','Saute onion, garlic and curry leaves in oil until golden.','Add curry powder, turmeric and lemongrass; fry 1 min.','Add jackfruit and coconut milk; simmer 20 min until gravy thickens.','Serve over rice.']::text[], ARRAY['lunch']::text[], 'plate', 350, 390, 8.2, 52.1, 12.8, 4.3, 2.1, 48, 0.1, 320, false),
  (192, 'Jackfruit Curry (Polos)', 'Sri Lankan', 'asian', 'vegan', false, 'curry', '3', '15 min', '40 min', 'A bold, dark Sri Lankan curry of young jackfruit that has absorbed a complex paste of roasted spices and tamarind — the island''s most celebrated vegetarian curry.', 'Using roasted (not raw) Sri Lankan curry powder is what gives polos its characteristic dark, complex flavour.', 'Traditional', NULL, ARRAY['400g young green jackfruit','2 tbsp Sri Lankan roasted curry powder','1 tsp chilli powder','1/2 tsp turmeric','1 cup coconut milk','1 onion, sliced','1 piece pandan leaf','1 lemongrass stalk, bruised','1 tsp tamarind concentrate','Coconut oil and salt']::text[], ARRAY['Boil jackfruit until tender; drain and roughly pull apart into chunks.','Saute onion with pandan and lemongrass until golden.','Add roasted curry powder, chilli and turmeric; fry 2 min.','Add jackfruit, tamarind, salt and coconut milk; simmer 20 min until gravy is deep and rich.','Adjust salt; remove lemongrass; serve with roti or rice.']::text[], ARRAY['dinner']::text[], 'bowl', 150, 280, 3.2, 22.4, 14.8, 2.1, 1.4, 42, 0, 385, false),
  (193, 'Wambatu Moju (Eggplant Pickle Curry)', 'Sri Lankan', 'asian', 'vegan', false, 'side', '2', '20 min', '30 min', 'Fried aubergine in a sweet, tangy and hot vinegar-based pickle sauce — one of the most distinctive Sri Lankan side dishes.', 'Salting and rinsing the aubergine before frying draws out moisture and gives a crisper, less oil-absorbent result.', 'Traditional', NULL, ARRAY['2 large aubergines, cubed and salted 15 min','1 onion, sliced into rings','4 green chillies, slit','3 tbsp white vinegar','2 tbsp sugar','1 tsp turmeric','1 tsp mustard seeds','1/2 tsp black pepper','Oil for frying','Salt to taste']::text[], ARRAY['Rinse and dry salted aubergine; deep-fry in batches until golden; drain.','Fry onion rings until crisp; drain.','In a little oil, fry mustard seeds; add vinegar, sugar, turmeric and pepper; bring to a simmer.','Add fried aubergine, onion and green chillies; toss to coat.','Cool before serving — the pickle is better at room temperature and improves overnight.']::text[], ARRAY['dinner']::text[], 'katori', 100, 230, 1.8, 18.5, 12.2, 3.2, 0.8, 28, 0, 485, false),
  (194, 'Sri Lankan Potato Curry (Ala Thel Dala)', 'Sri Lankan', 'asian', 'vegan', false, 'curry', '2', '10 min', '25 min', 'Dry-fried potatoes in a thick Sri Lankan spice paste with coconut milk — a rustic, intensely flavoured everyday curry.', 'Cooking uncovered after adding coconut milk allows the moisture to evaporate and leaves the potatoes in a clingy spice coating rather than a watery curry.', 'Traditional', NULL, ARRAY['3 medium potatoes, cubed','1 onion, sliced','1 tsp Sri Lankan curry powder','1/2 tsp turmeric','1/2 tsp chilli powder','8 curry leaves','1/2 cup coconut milk','2 tbsp coconut oil','Salt and lime juice to finish']::text[], ARRAY['Parboil potatoes 8 min until just starting to soften; drain.','Heat coconut oil; fry onion with curry leaves until golden.','Add curry powder, turmeric and chilli; fry 1 min.','Add potatoes; toss to coat in spices.','Add coconut milk and salt; cook uncovered until liquid reduces and potatoes are coated in a thick, dry sauce; finish with lime.']::text[], ARRAY['dinner']::text[], 'bowl', 150, 250, 3.2, 28.5, 12.8, 2.1, 0.9, 28, 0, 185, false),
  (195, 'Ulundu Vadai (Urad Dal Fritter)', 'Sri Lankan', 'asian', 'vegan', false, 'snack', '2', '4 hrs', '20 min', 'Crispy, golden doughnuts of urad dal batter spiced with cumin and green chilli — the Sri Lankan vadai, eaten with coconut sambol.', 'Grind the dal with as little water as possible — a thick batter gives a lighter, crisper vadai; too thin and they will absorb oil and turn heavy.', 'Traditional', NULL, ARRAY['1 cup urad dal, soaked 4 hrs','1 tsp cumin seeds','2 green chillies, minced','1 small onion, very finely diced','8 curry leaves, chopped','Salt to taste','Oil for deep frying','Coconut sambol to serve']::text[], ARRAY['Drain and grind urad dal with minimal water to a thick, smooth batter; it should hold its shape.','Fold in cumin, chillies, onion and curry leaves.','Wet hands; shape batter into a flat disc and make a hole in the centre.','Deep fry at 175°C until golden on both sides — about 3-4 min total.','Drain; serve hot with coconut sambol.']::text[], ARRAY['snack']::text[], 'serving', 80, 210, 7.2, 16.8, 8.9, 3.2, 2.1, 48, 0, 280, false),
  (196, 'Kokis (Crispy Coconut Snack)', 'Sri Lankan', 'asian', 'egg', true, 'snack', '4', '15 min', '20 min', 'Intricately shaped, crispy Sri Lankan cookies made by dipping a hot iron mould into coconut batter and frying — a Sinhala New Year staple.', 'The mould must be very hot before dipping in batter — this is what causes the characteristic crispy, lacy texture.', 'Traditional', NULL, ARRAY['1 cup rice flour','1/2 cup coconut milk','1 egg','Pinch of salt','Oil for deep frying (and for the kokis mould)','Kokis mould (a special iron mould with a flower or geometric pattern)']::text[], ARRAY['Whisk rice flour, coconut milk, egg and salt into a smooth, thin batter.','Heat oil in a deep pan; submerge the kokis mould in the hot oil for 1 min to heat through.','Dip the hot mould into the batter up to the rim — it should sizzle.','Immediately submerge mould back in oil; the batter will puff and release from the mould.','Fry until golden and crisp; drain; cool fully before storing.']::text[], ARRAY['snack']::text[], 'piece', 40, 180, 2.8, 18.5, 9.2, 0.6, 0.8, 22, 0.15, 85, false),
  (197, 'Konda Kavum (Rice Flour Sweet)', 'Sri Lankan', 'asian', 'vegan', true, 'dessert', '4', '30 min', '20 min', 'Deep-fried Sri Lankan sweetmeats made from rice flour and jaggery — golden, soft within and slightly crispy outside, traditionally made for Sinhala New Year.', 'Frying at a lower temperature is essential — kavum needs time to cook through before the outside browns.', 'Traditional', NULL, ARRAY['2 cups rice flour','1/2 cup jaggery or dark brown sugar, dissolved in 1 cup water','1/4 cup thick coconut milk','1/2 tsp turmeric','Oil for deep frying']::text[], ARRAY['Strain dissolved jaggery; mix with coconut milk and turmeric.','Gradually add liquid to rice flour, mixing to a thick, smooth batter that is pourable.','Heat oil to 160°C; drop heaped tablespoons of batter in.','Fry slowly, spooning oil over the top, until golden and cooked through — about 5-6 min.','Drain; cool slightly; the texture should be slightly chewy inside.']::text[], ARRAY['snack']::text[], 'piece', 50, 220, 1.8, 28.5, 10.2, 0.6, 0.4, 18, 0, 12, false),
  (198, 'Thala Guli (Sesame Energy Ball)', 'Sri Lankan', 'asian', 'veg', true, 'dessert', '4', '20 min', '0 min', 'Compact, intensely nutty balls of toasted sesame and jaggery — Sri Lanka''s original energy snack, made without any cooking.', 'Roll the balls while the mixture is still warm — once cooled, it becomes too stiff and crumbles rather than binding.', 'Traditional', NULL, ARRAY['1 cup white sesame seeds','4 tbsp jaggery or dark brown sugar','1 tbsp honey or coconut syrup','Pinch of cardamom powder','Pinch of salt']::text[], ARRAY['Dry-toast sesame seeds in a pan on low heat, stirring constantly, until golden and fragrant; cool.','Blend half the sesame to a rough powder; leave the other half whole for texture.','Warm jaggery with honey until melted; mix into sesame off the heat.','Add cardamom and salt; mix well.','While still warm, roll into small balls; cool completely to firm up.']::text[], ARRAY['snack']::text[], 'piece', 30, 160, 5.2, 16.8, 9.4, 2.1, 2.8, 186, 0, 95, false),
  (199, 'Avocado Toast with Poached Egg', 'Western European', 'european', 'egg', true, 'main', '2', '5 min', '8 min', 'Creamy mashed avocado on toasted sourdough topped with a softly poached egg, lemon and chilli flakes — the modern brunch classic that earned its reputation.', 'Do not blend the avocado — a rough mash with visible chunks has far better texture than a smooth paste.', 'Traditional', NULL, ARRAY['2 thick slices sourdough bread, toasted','2 ripe avocados','2 eggs','1 tbsp white wine vinegar','Juice of half a lemon','Pinch of chilli flakes','Sea salt and black pepper','Extra virgin olive oil to drizzle','Microgreens or radish slices to garnish']::text[], ARRAY['Bring a pan of water to a gentle simmer; add vinegar.','Mash avocado with lemon juice, salt and pepper to a rough, textured mash.','Swirl the simmering water; slide eggs in and poach 3 min until whites are just set.','Spread avocado generously on toast; top with a poached egg.','Drizzle olive oil; scatter chilli flakes and garnish; serve immediately.']::text[], ARRAY['breakfast']::text[], 'plate', 180, 320, 14.2, 28.5, 16.8, 6.2, 2.8, 78, 0.54, 385, false),
  (200, 'Bircher Muesli', 'Western European', 'european', 'veg', true, 'main', '2', '10 min', '0 min', 'Rolled oats soaked overnight in apple juice with yoghurt and grated apple — a Swiss morning staple that is creamy, fresh and completely no-cook.', 'Grating the apple just before serving (rather than the night before) prevents browning and keeps the flavour bright and fresh.', 'Traditional', NULL, ARRAY['1.5 cups rolled oats','1 cup unsweetened apple juice','1/2 cup natural yoghurt','1 large apple, grated (skin on)','2 tbsp honey','1/2 tsp cinnamon','2 tbsp mixed seeds (pumpkin, sunflower)','1/4 cup mixed berries to serve','Handful of toasted nuts to scatter']::text[], ARRAY['Mix oats with apple juice; stir, cover and refrigerate overnight.','In the morning, stir in yoghurt, grated apple, honey and cinnamon.','Add a splash of milk if the consistency is too thick.','Spoon into bowls; top with berries, seeds and toasted nuts.','Serve straight from the fridge — it is meant to be eaten cold.']::text[], ARRAY['breakfast']::text[], 'bowl', 250, 360, 12.5, 52, 9.5, 7.2, 2.8, 185, 0.35, 68, false),
  (201, 'French Toast with Berries', 'Western European', 'european', 'egg', true, 'main', '2', '5 min', '10 min', 'Thick-cut bread soaked in a vanilla and cinnamon egg custard and fried until golden — the Gallic classic served with fresh berries and a maple drizzle.', 'Use day-old brioche — it is slightly drier and absorbs the custard without becoming soggy.', 'Traditional', NULL, ARRAY['4 slices thick brioche or challah bread','2 eggs','1/2 cup whole milk','1/2 tsp vanilla extract','1/2 tsp ground cinnamon','1 tbsp butter','1 cup mixed fresh berries','Maple syrup to drizzle','Icing sugar to dust (optional)']::text[], ARRAY['Whisk eggs, milk, vanilla and cinnamon until smooth.','Soak bread slices in the custard 30 seconds each side until saturated.','Melt butter in a wide pan over medium heat.','Fry soaked bread 2-3 min each side until deeply golden.','Serve with fresh berries, a drizzle of maple syrup and a dusting of icing sugar.']::text[], ARRAY['breakfast']::text[], 'plate', 180, 380, 12.5, 48.2, 14.8, 2.1, 2.4, 156, 0.6, 285, false),
  (202, 'Croque Madame (Vegetarian)', 'Western European', 'european', 'egg', true, 'main', '2', '10 min', '15 min', 'A grilled gruyere and mustard sandwich covered in bechamel and crowned with a fried egg — the grande dame of French cafe sandwiches in a vegetarian guise.', 'The bechamel should be very thick — it needs to hold its shape on top of the bread without dripping.', 'Traditional', NULL, ARRAY['4 slices sourdough or white sandwich bread','100g gruyere or emmental, grated','2 tsp Dijon mustard','For bechamel: 1 tbsp butter, 1 tbsp flour, 150ml milk, pinch of nutmeg','2 eggs, fried sunny side up','Salt and pepper']::text[], ARRAY['Make bechamel: melt butter, stir in flour 1 min, whisk in milk until smooth and thick; season with nutmeg.','Spread mustard inside sandwiches; fill with most of the cheese; press together.','Toast sandwiches in a buttered pan 2 min each side until golden.','Place on a baking tray; spread bechamel on top; scatter remaining cheese; grill 3-4 min until bubbling.','Top each sandwich with a fried egg; serve immediately.']::text[], ARRAY['breakfast']::text[], 'plate', 200, 410, 18.5, 28, 18.5, 1.2, 2.1, 285, 0.8, 520, false),
  (203, 'Eggs Benedict Florentine', 'Western European', 'european', 'egg', true, 'main', '2', '10 min', '15 min', 'English muffins topped with wilted spinach and poached eggs under a cascade of rich, lemony hollandaise — the most luxurious vegetarian eggs Benedict.', 'Hollandaise splits when too hot — keep the water at a gentle simmer and remove from heat regularly as you whisk.', 'Traditional', NULL, ARRAY['2 English muffins, split and toasted','200g fresh spinach, wilted and excess water squeezed out','4 eggs','For hollandaise: 3 egg yolks, 150g butter, lemon juice, salt, white pepper, pinch of cayenne']::text[], ARRAY['Make hollandaise: whisk yolks with lemon juice in a bowl over simmering water until pale; whisk in melted butter drop by drop until thick; season.','Poach eggs in simmering water with vinegar for 3 min.','Season spinach with salt and pepper; pile onto toasted muffins.','Place poached eggs on spinach.','Spoon hollandaise generously over each egg; dust with cayenne.']::text[], ARRAY['breakfast']::text[], 'plate', 250, 420, 18.5, 28.5, 18.2, 2.1, 3.8, 156, 1.2, 485, false),
  (204, 'Mushroom Risotto', 'Western European', 'european', 'veg', false, 'main', '2', '10 min', '35 min', 'Arborio rice stirred slowly with wine and hot stock until each grain is enveloped in a silky, mushroom-scented sauce — risotto done with care.', 'The final rest off the heat with butter stirred in — the mantecatura — is what transforms good risotto into great risotto.', 'Traditional', NULL, ARRAY['1 cup arborio rice','200g mixed mushrooms (portobello, cremini, shiitake)','1 onion, finely diced','2 garlic cloves, minced','100ml dry white wine','750ml hot vegetable stock','50g parmesan or vegetarian equivalent, grated','2 tbsp butter','Olive oil, thyme, salt and pepper','Parsley to garnish']::text[], ARRAY['Saute mushrooms in butter over high heat until golden; set aside.','In the same pan, soften onion in oil; add garlic and rice; stir 2 min until rice is translucent at edges.','Add wine; stir until absorbed.','Add hot stock one ladle at a time, stirring constantly and waiting for each ladle to be absorbed before adding the next — about 20-22 min.','Fold in mushrooms and parmesan; stir in remaining butter; rest 2 min; garnish and serve.']::text[], ARRAY['dinner']::text[], 'plate', 300, 390, 14.5, 52, 12.5, 2.8, 2.1, 185, 0.35, 520, false),
  (205, 'Gnocchi al Pomodoro', 'Western European', 'european', 'veg', false, 'main', '2', '10 min', '25 min', 'Pillowy potato gnocchi tumbled in a bright, slow-cooked San Marzano tomato sauce and finished with torn basil and parmesan.', 'Crushing the tomatoes by hand (not blending) keeps texture — a smooth sauce makes gnocchi feel heavy rather than light.', 'Traditional', NULL, ARRAY['400g fresh or good-quality dried gnocchi','1 can (400g) San Marzano or whole plum tomatoes','3 garlic cloves, sliced','1/4 tsp chilli flakes','3 tbsp olive oil','Handful of fresh basil leaves','Parmesan to serve','Salt and pepper']::text[], ARRAY['Crush tomatoes by hand; saute garlic in olive oil until golden; add chilli.','Add tomatoes; season with salt; simmer 20 min until sauce is deep red and slightly reduced.','Cook gnocchi in boiling salted water until they float — about 2 min; drain.','Toss gnocchi directly into the tomato sauce; fold gently.','Serve immediately with torn basil and parmesan.']::text[], ARRAY['dinner']::text[], 'plate', 300, 370, 12.5, 48, 11.5, 2.2, 1.8, 45, 0.15, 380, false),
  (206, 'Vegetarian Shepherd''s Pie', 'Western European', 'european', 'veg', false, 'main', '3', '20 min', '45 min', 'A deep dish of lentil and root vegetable stew topped with buttery mashed potato and baked until the crust is golden and crisp — proper cold-weather comfort.', 'Roughing the mash surface with a fork creates peaks that catch heat and brown beautifully — a smooth surface stays pale.', 'Traditional', NULL, ARRAY['1 cup green lentils, cooked','2 carrots, diced','2 celery stalks, diced','1 onion, diced','2 garlic cloves','1 cup frozen peas','1 tbsp tomato paste','1 cup vegetable stock','1 tsp thyme and rosemary','For mash: 4 large potatoes, 50g butter, warm milk, salt']::text[], ARRAY['Saute onion, carrot and celery until soft; add garlic and herbs; cook 1 min.','Stir in tomato paste; add lentils, peas and stock; simmer 10 min until slightly thick.','Transfer to a baking dish; season generously.','Boil potatoes; mash with butter and milk until smooth; season.','Spread mash over the filling; rough the top with a fork; bake at 200°C for 25 min until golden.']::text[], ARRAY['dinner']::text[], 'plate', 350, 410, 14.2, 52.3, 8.1, 9.8, 3.2, 68, 0.05, 385, false),
  (207, 'Ribollita (Tuscan Bread Soup)', 'Western European', 'european', 'veg', false, 'soup', '3', '15 min', '40 min', 'Leftover bread and cannellini beans simmered with cavolo nero and vegetables into the thickest, most satisfying Tuscan soup.', 'Ribollita means ''reboiled'' — it is actually better re-heated, when the bread has fully absorbed the broth and become part of the soup.', 'Traditional', NULL, ARRAY['200g stale sourdough or ciabatta, torn','1 can cannellini beans','200g cavolo nero or kale, roughly chopped','2 carrots, diced','2 celery stalks, diced','1 onion, diced','2 garlic cloves','1 can chopped tomatoes','1 litre vegetable stock','3 tbsp olive oil','Parmesan rind (optional)','Fresh thyme and rosemary']::text[], ARRAY['Saute onion, carrot and celery in olive oil until soft; add garlic and herbs.','Add tomatoes, beans and stock; simmer 20 min; add parmesan rind if using.','Add cavolo nero; cook 10 min more.','Stir in torn bread; cook until bread absorbs liquid and soup is very thick.','Serve in bowls with a generous drizzle of raw olive oil — best re-heated the next day.']::text[], ARRAY['dinner']::text[], 'bowl', 350, 330, 14.2, 38.5, 11.8, 8.3, 3.2, 185, 0.3, 645, false),
  (208, 'Bruschetta al Pomodoro', 'Western European', 'european', 'vegan', false, 'snack', '2', '10 min', '5 min', 'Grilled bread rubbed with garlic and loaded with diced ripe tomato, fresh basil and a generous pour of good olive oil — Italy''s greatest simple food.', 'The garlic rub on hot toast is not optional — it melts into the bread and is the signature flavour of a proper bruschetta.', 'Traditional', NULL, ARRAY['4 thick slices sourdough or ciabatta','3 large ripe tomatoes, deseeded and diced','1 large garlic clove, halved','10 fresh basil leaves, torn','3 tbsp extra virgin olive oil','1/2 tsp sea salt flakes','Pinch of black pepper','Optional: pinch of chilli flakes or balsamic glaze']::text[], ARRAY['Grill or toast bread slices until charred and crisp.','While hot, vigorously rub cut garlic over one side of each slice.','Toss diced tomato with olive oil, salt and basil; rest 5 min.','Spoon tomato generously onto garlic-rubbed bread.','Drizzle more olive oil; add pepper; serve immediately.']::text[], ARRAY['snack']::text[], 'serving', 110, 220, 7.5, 28.5, 11.2, 2.1, 1.8, 52, 0.1, 385, false),
  (209, 'Cheese and Herb Scones', 'Western European', 'european', 'egg', true, 'snack', '4', '15 min', '18 min', 'Buttery, flaky scones packed with mature cheddar and fresh chives — British afternoon baking at its most reliable and satisfying.', 'The secret to risen scones is cold butter, cold milk and minimal mixing — warmth and overworking develop gluten and kill the lift.', 'Traditional', NULL, ARRAY['2 cups self-raising flour','1 tsp baking powder','50g cold butter, cubed','120ml cold milk','100g mature cheddar, grated','2 tbsp fresh chives, finely chopped','1/2 tsp mustard powder','Salt and pepper','Egg wash to brush']::text[], ARRAY['Rub cold butter into flour until it resembles breadcrumbs; stir in baking powder, salt, mustard powder and pepper.','Mix in most of the cheese and the chives.','Add cold milk gradually; mix to a shaggy dough — do not overwork.','Pat to 2cm thickness; cut into rounds; place on a lined tray.','Brush with egg wash; scatter remaining cheese; bake at 220°C for 15-18 min until risen and golden.']::text[], ARRAY['snack']::text[], 'piece', 70, 210, 8.2, 22.5, 8.8, 0.9, 1.2, 185, 0.28, 420, false),
  (210, 'Vegetable Crudites with Whipped Ricotta', 'Western European', 'european', 'veg', false, 'snack', '3', '15 min', '0 min', 'A platter of seasonal raw vegetables arranged around a bowl of whipped ricotta with lemon and herbs — a light, elegant European appetiser.', 'Season the ricotta assertively — it is meant to be the dip, not just a white backdrop, and underseasoned ricotta is bland.', 'Traditional', NULL, ARRAY['200g ricotta','Zest and juice of half a lemon','2 tbsp olive oil','1 garlic clove, minced','Salt and pepper','Selection of vegetables: carrots, cucumber, radish, celery, bell pepper strips, fennel, endive leaves','Fresh dill and chives to garnish']::text[], ARRAY['Whip ricotta with lemon zest, juice, olive oil and garlic until smooth and creamy; season generously.','Spoon into a serving bowl; create a well in the centre; drizzle olive oil into the well.','Trim and cut all vegetables into dippable lengths or wedges.','Arrange vegetables around the dip in groups by colour and shape.','Scatter fresh herbs over the dip; serve chilled.']::text[], ARRAY['snack']::text[], 'serving', 150, 180, 8.2, 12.5, 9.8, 3.1, 0.8, 185, 0.35, 185, false),
  (211, 'Huevos Rancheros', 'Mexican', 'latin_american', 'egg', false, 'main', '2', '10 min', '20 min', 'Fried eggs served on warm tortillas in a robust tomato and chilli salsa ranchera — the Mexican ranchero''s breakfast that fuels a morning of work.', 'Charring the tomatoes and chillies before blending gives the salsa ranchera a distinctive smokiness that raw-blended versions lack.', 'Traditional', NULL, ARRAY['4 eggs','4 corn tortillas','For salsa ranchera: 3 tomatoes, 2 jalapeños, 1/2 onion, 2 garlic cloves, 1 tsp cumin','1/2 cup black beans, warmed','Mexican crema or sour cream','Fresh coriander and lime to serve','Vegetable oil for frying']::text[], ARRAY['Char tomatoes, jalapeños and onion under a grill until blistered; blend with garlic and cumin; season.','Fry salsa in a little oil 5 min until it deepens in colour; keep warm.','Warm tortillas in a dry pan; fry eggs sunny side up.','Place two tortillas on each plate; spoon salsa over each; set a fried egg on top.','Add beans; drizzle crema; scatter coriander; squeeze lime.']::text[], ARRAY['breakfast']::text[], 'plate', 300, 350, 14.5, 32.8, 16.2, 5.4, 3.2, 95, 0.68, 485, false),
  (212, 'Chilaquiles Verdes', 'Mexican', 'latin_american', 'egg', false, 'main', '2', '10 min', '20 min', 'Stale tortilla chips simmered briefly in a bright tomatillo salsa verde until they soften and absorb the sauce — served with eggs and crema.', 'The chips should be just barely softened — remove from heat 30 seconds before they look done, as carryover heat finishes them.', 'Traditional', NULL, ARRAY['200g good quality tortilla chips','300ml tomatillo salsa verde (canned or fresh)','1/2 cup vegetable stock','2 eggs (optional: fried or poached)','1/4 cup crema or sour cream','50g crumbled queso fresco or feta','1/4 onion, finely sliced into rings','Fresh coriander and lime']::text[], ARRAY['Warm salsa verde with stock in a wide pan until simmering.','Add tortilla chips all at once; fold gently until chips are coated and beginning to soften — about 2-3 min; do not stir too much.','Plate immediately while the chips still have some texture.','Top with fried or poached egg, crema, cheese and onion.','Garnish with coriander and a wedge of lime.']::text[], ARRAY['breakfast']::text[], 'plate', 300, 370, 15.2, 38.5, 16.8, 4.2, 2.1, 185, 0.6, 680, false),
  (213, 'Molletes with Refried Beans and Pico', 'Mexican', 'latin_american', 'veg', false, 'main', '2', '10 min', '10 min', 'Toasted bolillo rolls spread with refried beans and melted cheese, topped with fresh pico de gallo — Mexico City''s beloved bread-and-beans breakfast.', 'Warm the beans properly before spreading — cold refried beans on toast taste dense and pasty; warm beans are creamy and loose.', 'Traditional', NULL, ARRAY['2 bolillo rolls (or baguette portions), halved','1 cup refried pinto beans, warmed','100g Oaxaca or mozzarella, shredded','For pico de gallo: 2 tomatoes, 1/4 onion, 1 jalapeño, coriander, lime juice, salt','Butter to spread (optional)']::text[], ARRAY['Make pico: finely dice tomatoes, onion and jalapeño; toss with coriander, lime juice and salt; rest 10 min.','Toast rolls cut-side down in a dry pan or oven until golden.','Spread warm refried beans generously on each half.','Scatter cheese over the beans; grill until bubbling.','Top with a generous spoonful of pico de gallo; serve immediately.']::text[], ARRAY['breakfast']::text[], 'plate', 200, 320, 14.5, 38.2, 9.8, 6.4, 2.8, 185, 0.35, 580, false),
  (214, 'Tamales de Elote (Sweet Corn Tamales)', 'Mexican', 'latin_american', 'veg', true, 'staple', '4', '40 min', '60 min', 'Soft, slightly sweet corn dough steamed in corn husks — the tamale in its most basic and most honest form.', 'The dough is ready when a small ball floats in a glass of cold water — this is the traditional Mexican freshness test.', 'Traditional', NULL, ARRAY['2 cups fresh or frozen corn kernels','1.5 cups masa harina','1/2 cup butter or lard, soft','1/4 cup sugar','1 tsp baking powder','1/2 tsp salt','Warm water or broth to adjust consistency','Corn husks, soaked in warm water 30 min to soften']::text[], ARRAY['Blend corn kernels to a rough paste.','Beat butter until fluffy; add masa harina, sugar, baking powder and salt; mix in corn paste.','Add warm broth or water to form a soft, spreadable dough.','Spread 2 tbsp dough on a soaked husk; fold sides in, fold bottom up.','Stand tamales upright in a steamer; steam 50-60 min until dough pulls cleanly from the husk.']::text[], ARRAY['breakfast']::text[], 'piece', 150, 280, 6.2, 32.5, 14.8, 2.1, 1.4, 45, 0.12, 385, false),
  (215, 'Avocado Tostada with Black Beans', 'Mexican', 'latin_american', 'veg', true, 'main', '2', '10 min', '10 min', 'A crisp, flat fried tortilla topped with refried black beans, smashed avocado, pickled jalapeños and crumbled cheese — the street-food tostada.', 'Build and eat tostadas immediately — they are designed to be crispy and will soften within minutes of topping.', 'Traditional', NULL, ARRAY['4 corn tortillas, fried flat until crisp','1 cup black beans, cooked and mashed','2 avocados, roughly smashed','Juice of 1 lime','Pickled jalapeños','1/4 cup queso fresco or feta, crumbled','Shredded cabbage or lettuce','Mexican crema','Coriander and salt']::text[], ARRAY['Fry tortillas flat in oil until completely crisp; drain on paper.','Season mashed black beans with cumin and salt; warm gently.','Season smashed avocado with lime juice and salt.','Spread beans on each tostada; add avocado; add cabbage.','Top with jalapeños, cheese, crema and coriander.']::text[], ARRAY['lunch']::text[], 'plate', 200, 340, 12.5, 32, 18.5, 9, 2.8, 165, 0.4, 385, false),
  (216, 'Enfrijoladas', 'Mexican', 'latin_american', 'veg', false, 'main', '2', '15 min', '20 min', 'Corn tortillas dipped in a thick, silky black bean sauce and folded with cheese inside — Mexico''s humbler, earthier cousin to enchiladas.', 'The bean sauce should coat the back of a spoon thickly — too thin and it soaks the tortilla into mush within seconds.', 'Traditional', NULL, ARRAY['8 corn tortillas','2 cups black beans, cooked','1 chipotle chilli (or 1 tsp chipotle paste)','1 garlic clove','1/2 onion','1/2 cup crumbled queso fresco or feta','Sour cream and fresh coriander to serve','Oil for frying tortillas briefly']::text[], ARRAY['Blend black beans with chipotle, garlic and onion, adding broth to reach a thick, pourable sauce; warm in a pan.','Briefly fry tortillas in oil 20 seconds each side to soften; drain.','Dip each tortilla in the warm bean sauce to coat; fold in half with a pinch of cheese inside.','Arrange two per plate; spoon more sauce over; add remaining cheese.','Serve with sour cream and coriander.']::text[], ARRAY['lunch']::text[], 'plate', 300, 370, 14.2, 42.8, 12.5, 7.3, 2.8, 185, 0.35, 520, false),
  (217, 'Black Bean Quesadilla', 'Mexican', 'latin_american', 'veg', true, 'main', '2', '10 min', '10 min', 'Flour tortillas filled with black beans, melted cheese and poblano pepper, pressed until crispy gold on the outside and gooey within.', 'Medium heat is essential — too hot and the tortilla burns before the cheese melts; too low and it dries out rather than crisping.', 'Traditional', NULL, ARRAY['4 large flour tortillas','1 cup black beans, drained','150g Oaxaca or mozzarella, shredded','1 poblano or green pepper, roasted and sliced','1/2 tsp cumin','Pinch of smoked paprika','Butter or oil for the pan','Sour cream and guacamole to serve']::text[], ARRAY['Season black beans with cumin and smoked paprika.','Lay a tortilla flat; scatter beans, cheese and pepper strips on one half; fold over.','Heat a little butter in a flat pan over medium heat.','Cook quesadilla 2-3 min each side, pressing gently, until both sides are golden and cheese has melted.','Cut into wedges; serve with sour cream and guacamole.']::text[], ARRAY['lunch']::text[], 'plate', 220, 360, 14.5, 38.2, 14.8, 6.2, 2.4, 285, 0.6, 520, false),
  (218, 'Pozole Verde (Green Hominy Soup)', 'Mexican', 'latin_american', 'vegan', false, 'soup', '3', '20 min', '40 min', 'A soul-warming green stew of hominy, tomatillos and pumpkin seeds, served with a feast of toppings — Mexico''s great ritual soup.', 'Frying the green paste in oil before adding liquid is the key step — it transforms a raw, sharp blend into a deep, complex broth base.', 'Traditional', NULL, ARRAY['1 can hominy (pozole), drained and rinsed','For green broth: 300g tomatillos, 1/2 cup pumpkin seeds toasted, 2 jalapeños, 2 garlic cloves, 1/4 onion, handful of epazote or coriander','1 litre vegetable stock','Salt to taste','Toppings: shredded cabbage, sliced radish, dried oregano, chilli flakes, lime, tostadas']::text[], ARRAY['Blend tomatillos, pumpkin seeds, jalapeños, garlic, onion and herbs with a little water to a smooth green paste.','Fry paste in hot oil 5 min, stirring constantly, until deep green and fragrant.','Add hominy and stock; simmer 25 min until hominy is tender and broth is rich.','Taste and season; adjust heat.','Ladle into deep bowls; set out all toppings for the table to add themselves.']::text[], ARRAY['dinner']::text[], 'bowl', 350, 320, 12.5, 38.2, 10.8, 7.4, 2.1, 95, 0.1, 485, false),
  (219, 'Enchiladas Verdes', 'Mexican', 'latin_american', 'veg', false, 'main', '2', '20 min', '25 min', 'Corn tortillas rolled around a cheese and bean filling, nestled in tomatillo salsa verde and baked until the sauce bubbles.', 'Softening the tortillas in oil before rolling prevents them from cracking and breaking when you fold them around the filling.', 'Traditional', NULL, ARRAY['8 corn tortillas','1 cup black beans or pinto beans, cooked','150g Oaxaca or mozzarella, shredded','400ml tomatillo salsa verde','1/2 cup Mexican crema','1/4 cup queso fresco to top','Coriander and onion to garnish']::text[], ARRAY['Briefly fry tortillas in oil to soften; do not crisp.','Mix beans with half the cheese; roll a spoonful inside each tortilla; place seam-down in a baking dish.','Pour salsa verde over to cover; scatter remaining cheese on top.','Bake at 190°C for 20 min until sauce is bubbling.','Drizzle crema; scatter queso fresco, coriander and onion; serve from the dish.']::text[], ARRAY['dinner']::text[], 'plate', 300, 390, 18.5, 38.2, 16.8, 6.4, 2.1, 385, 0.6, 680, false),
  (220, 'Calabacitas', 'Mexican', 'latin_american', 'veg', false, 'side', '2', '10 min', '20 min', 'A Mexican summer squash saute with corn, poblano and cheese — one of the most elemental and beloved side dishes in the Mexican kitchen.', 'Pull the pan from heat as soon as you add the cheese — you want it to melt softly into the vegetables, not fry and become rubbery.', 'Traditional', NULL, ARRAY['3 medium courgettes, cubed','1 cup corn kernels (fresh or frozen)','1 poblano pepper, diced','1 onion, diced','3 garlic cloves, minced','100g queso Chihuahua or mozzarella, cubed','2 tbsp butter','Salt, pepper and dried oregano','Fresh epazote or coriander']::text[], ARRAY['Melt butter; saute onion and poblano 5 min until soft; add garlic.','Add courgette and cook 8 min, stirring occasionally, until just tender.','Stir in corn; cook 3 min; season with salt, pepper and oregano.','Fold in cheese cubes; remove from heat and let cheese soften from the residual heat.','Garnish with epazote or coriander; serve as a side or over rice.']::text[], ARRAY['dinner']::text[], 'bowl', 180, 230, 11.5, 18.5, 14.2, 3.8, 1.2, 185, 0.4, 420, false),
  (221, 'Fideo Seco (Dry Vermicelli)', 'Mexican', 'latin_american', 'veg', false, 'main', '2', '10 min', '25 min', 'Thin vermicelli pasta toasted in a pan then cooked in tomato broth until all the liquid absorbs — a comforting Mexican pasta dish that is deeply savoury.', 'Toasting the dry noodles until truly golden is the defining step — under-toasted fideo tastes like plain pasta; properly toasted fideo is nutty and complex.', 'Traditional', NULL, ARRAY['200g fideo noodles or thin vermicelli, broken','1 can chopped tomatoes','1 chipotle chilli (or 1/2 tsp chipotle paste)','2 garlic cloves','1/4 onion','1.5 cups vegetable stock','2 tbsp vegetable oil','Salt','Crema, avocado and lime to serve']::text[], ARRAY['Blend tomatoes, chipotle, garlic and onion to a smooth sauce.','Toast dry fideo in oil over medium heat, stirring constantly, until golden — about 4-5 min; do not burn.','Pour blended tomato sauce into the pan — it will sizzle dramatically; stir.','Add stock; bring to a boil; reduce to a simmer; cook uncovered until liquid fully absorbs.','Serve with crema drizzled over, avocado slices and lime.']::text[], ARRAY['dinner']::text[], 'plate', 250, 310, 8.5, 48, 12.5, 2.8, 2.1, 35, 0, 485, false),
  (222, 'Guacamole and Totopos', 'Mexican', 'latin_american', 'vegan', false, 'snack', '2', '10 min', '0 min', 'Hand-mashed avocado with onion, chilli, coriander and lime — made fresh in a molcajete and eaten with crisp tortilla chips.', 'Pressing a piece of cling film directly onto the surface of leftover guacamole — not over the bowl — is the only method that truly delays browning.', 'Traditional', NULL, ARRAY['3 ripe Hass avocados','1/2 small white onion, very finely minced','1-2 serrano or jalapeño chillies, minced','1/4 cup fresh coriander, chopped','Juice of 1 lime','Salt to taste','Corn tortilla chips (totopos) to serve']::text[], ARRAY['Grind onion and chilli to a paste in a molcajete (or use a bowl and fork).','Add avocado; mash roughly — texture should be chunky, not smooth.','Fold in coriander; squeeze in lime juice; season with salt.','Taste and adjust chilli and lime.','Serve immediately with totopos — guacamole begins to oxidise within 30 min.']::text[], ARRAY['snack']::text[], 'serving', 120, 290, 4.2, 18.5, 21.3, 8.1, 1.8, 28, 0, 185, false),
  (223, 'Churros with Chocolate Dipping Sauce', 'Mexican', 'latin_american', 'veg', true, 'dessert', '3', '15 min', '20 min', 'Crispy, golden fried dough coated in cinnamon sugar, served with a thick drinking-chocolate dip — the street-fair sweet of the Spanish-speaking world.', 'Pipe churros directly into the oil from a piping bag — scissors in your other hand cut each one cleanly at the right length.', 'Traditional', NULL, ARRAY['1 cup water','1/2 tsp salt','1 tsp sugar','1 cup plain flour','Oil for deep frying','For coating: 1/2 cup sugar + 1 tsp cinnamon','For dip: 150ml cream, 80g dark chocolate (70%), pinch of chilli']::text[], ARRAY['Bring water, salt and sugar to a boil; remove from heat; beat in flour to a smooth, stiff dough.','Cool slightly; pipe into hot oil (175°C) through a star nozzle in 12cm lengths; fry 3-4 min until golden.','Drain; immediately roll in cinnamon sugar.','Make dip: heat cream; pour over chopped chocolate; stir in chilli; stir until smooth.','Serve churros alongside the chocolate dipping sauce.']::text[], ARRAY['snack']::text[], 'serving', 100, 390, 6.5, 38.2, 18.3, 2.1, 1.2, 85, 0.2, 285, false),
  (224, 'Pepino con Limón y Chile (Cucumber Snack)', 'Mexican', 'latin_american', 'vegan', true, 'snack', '2', '5 min', '0 min', 'Cucumber spears dressed with lime juice, chilli powder and salt — Mexico''s purest, most refreshing street snack that needs no recipe, only quality.', 'Tajin (a blend of chilli, lime and salt) is the ideal seasoning if you can find it — it is pre-balanced and requires no adjustment.', 'Traditional', NULL, ARRAY['2 medium cucumbers','Juice of 2 limes','1 tsp chilli powder (Tajin or pure ancho chilli)','1 tsp sea salt flakes','Optional: jicama spears, mango slices or watermelon to add variety']::text[], ARRAY['Cut cucumbers into long spears or rounds.','Arrange on a plate or in a cup.','Squeeze lime juice generously over all the pieces.','Dust with chilli powder and salt flakes.','Serve immediately and eat with your hands.']::text[], ARRAY['snack']::text[], 'bowl', 150, 60, 1.2, 12.5, 0.3, 1.8, 0.4, 28, 0, 580, false),
  (225, 'Msemen (Moroccan Layered Flatbread)', 'North African', 'middle_eastern', 'veg', true, 'staple', '3', '30 min', '20 min', 'Flaky, laminated Moroccan griddle bread folded with butter and semolina — eaten warm with honey and argan oil for a quintessential Marrakchi morning.', 'The double folding and laminating step is what creates the characteristic flaky layers — skipping it produces a dense flatbread.', 'Traditional', NULL, ARRAY['2 cups plain flour','1/2 cup fine semolina','1 tsp salt','1 tsp sugar','1 tsp instant yeast','Warm water to mix','3 tbsp melted butter and 3 tbsp vegetable oil for laminating','Extra semolina for dusting','Honey and argan oil to serve']::text[], ARRAY['Mix flour, semolina, salt, sugar and yeast; add warm water to make a smooth, elastic dough; knead 10 min; rest 30 min.','Divide into balls; flatten each thin; brush with butter-oil mix; sprinkle semolina; fold in thirds then thirds again to form a square.','Rest 5 min; flatten each square thin again.','Cook on a dry griddle 3-4 min per side until golden and slightly puffed.','Drizzle honey and argan oil; serve warm.']::text[], ARRAY['breakfast']::text[], 'piece', 90, 290, 7.2, 36.8, 11.5, 1.2, 2.1, 28, 0.15, 385, false),
  (226, 'Baghrir (Thousand-Hole Pancakes)', 'North African', 'middle_eastern', 'egg', true, 'staple', '3', '10 min', '20 min', 'Semolina pancakes riddled with a honeycomb of holes, cooked only on one side, and served with a warm butter-and-honey dipping sauce.', 'Cook on one side only — the holes form as steam rises through the batter, and flipping collapses them and ruins the texture.', 'Traditional', NULL, ARRAY['1 cup fine semolina','1/2 cup plain flour','1 tsp instant yeast','1 tsp baking powder','1 egg','1.5 cups warm water','Pinch of salt','For sauce: 3 tbsp butter, 3 tbsp honey warmed together']::text[], ARRAY['Blend all batter ingredients until completely smooth; rest 15 min until slightly foamy.','Heat a lightly oiled non-stick pan over medium heat.','Pour a ladle of batter; cook on one side only — do not flip; holes will form on the surface as it cooks.','Remove when the surface is fully set and no wet batter remains.','Dip each pancake in warm butter-honey sauce before each bite.']::text[], ARRAY['breakfast']::text[], 'piece', 120, 270, 8.2, 35.4, 10.8, 1.2, 2.1, 48, 0.18, 285, false),
  (227, 'Sfenj (Moroccan Doughnuts)', 'North African', 'middle_eastern', 'vegan', true, 'snack', '4', '30 min', '15 min', 'Airy, yeasted Moroccan ring doughnuts fried golden and rolled in sugar — sold by street vendors in the early morning across the Maghreb.', 'The dough should be sticky and loose — a stiffer dough produces dense, bready doughnuts rather than the light, airy sfenj.', 'Traditional', NULL, ARRAY['2 cups plain flour','1 tsp instant yeast','1 tsp salt','1 tsp sugar','Warm water (approx 200ml) to make a sticky dough','Oil for deep frying','Sugar for rolling']::text[], ARRAY['Dissolve yeast in warm water; combine with flour, salt and sugar; beat to a sticky, loose dough; do not add more flour.','Cover and rise 1 hour until doubled and bubbly.','Wet hands; take a ball of dough; poke a hole through the centre; stretch into a ring.','Deep fry at 175°C until golden on both sides — 3-4 min total.','Drain briefly; roll in sugar; eat warm.']::text[], ARRAY['breakfast']::text[], 'piece', 70, 240, 3.8, 28.5, 10.2, 0.9, 1.8, 12, 0, 285, false),
  (228, 'Sellou (Roasted Flour Energy Bite)', 'North African', 'middle_eastern', 'veg', true, 'snack', '6', '20 min', '25 min', 'A Moroccan sweet of dry-roasted flour, sesame, almonds and honey — no baking needed, shaped into pyramids, eaten especially during Ramadan.', 'Roasting the flour until genuinely golden (not just warm) is what gives sellou its distinctive nutty, toasty depth.', 'Traditional', NULL, ARRAY['2 cups plain flour','1/2 cup sesame seeds, toasted','1/2 cup almonds, toasted and coarsely ground','1/2 cup honey or smen','3 tbsp butter or argan oil','1 tsp ground cinnamon','1/2 tsp ground anise','1/2 tsp ground ginger','Pinch of salt','Icing sugar to dust']::text[], ARRAY['Dry-roast flour in a pan over medium heat, stirring constantly, until golden and nutty — about 20 min; cool.','Mix roasted flour with ground almonds, sesame, cinnamon, anise, ginger and salt.','Melt butter into honey; pour over dry mixture; stir until it clumps.','Shape into small pyramids or balls; dust with icing sugar.','Serve at room temperature; store in an airtight tin for up to two weeks.']::text[], ARRAY['snack']::text[], 'piece', 50, 180, 5.2, 20.1, 8.9, 2.1, 1.8, 95, 0.1, 45, false),
  (229, 'Couscous Tfaya (Caramelised Onion Couscous)', 'North African', 'middle_eastern', 'egg', false, 'main', '3', '10 min', '45 min', 'A mound of steamed couscous crowned with the Moroccan ''tfaya'' — a silky, caramelised onion and raisin sauce scented with ras el hanout and cinnamon.', 'Low and slow is the only way to caramelise onions properly — the 30-minute cook time is not optional and cannot be rushed on high heat.', 'Traditional', NULL, ARRAY['2 cups couscous, steamed','2 large onions, thinly sliced','1/2 cup raisins','1 tsp ras el hanout','1 tsp cinnamon','1/2 tsp ginger','1/2 tsp turmeric','Pinch of saffron','3 tbsp olive oil','2 tbsp honey','1/2 cup water','Salt and black pepper','Fried almonds and hard-boiled egg to garnish']::text[], ARRAY['Saute onions in oil on low heat for 25-30 min until deeply caramelised and sticky.','Add spices, saffron, raisins, honey and water; cook 10 min until thick and jammy.','Steam couscous with butter and salt until fluffy and light.','Mound couscous on a serving platter; make a well in the centre.','Pour tfaya into the well; garnish with fried almonds and egg slices; serve.']::text[], ARRAY['dinner']::text[], 'plate', 300, 420, 12.5, 52, 14.5, 3.2, 2.8, 45, 0.35, 280, false),
  (230, 'Loubia (White Bean Stew)', 'North African', 'middle_eastern', 'vegan', false, 'curry', '2', '10 min', '30 min', 'Creamy cannellini beans in a deeply spiced tomato and cumin broth — a staple of the Moroccan and Algerian table, eaten with crusty khobz bread.', 'Mashing a quarter of the beans into the broth creates the thick, velvety texture that distinguishes loubia from a watery bean soup.', 'Traditional', NULL, ARRAY['2 cans cannellini beans','1 can chopped tomatoes','1 onion, finely diced','4 garlic cloves, minced','1 tsp cumin','1 tsp paprika','1/2 tsp chilli flakes','1 tsp harissa paste','3 tbsp olive oil','Fresh parsley and lemon to serve']::text[], ARRAY['Saute onion in olive oil until golden; add garlic, cumin and paprika; fry 1 min.','Add tomatoes, harissa and chilli; simmer 10 min.','Add beans and enough water to just cover; simmer 15 min until broth is rich.','Mash a few beans against the side of the pan to thicken.','Drizzle olive oil; scatter parsley; serve with a wedge of lemon and bread.']::text[], ARRAY['lunch']::text[], 'bowl', 250, 310, 12.5, 35.8, 11.2, 8.4, 3.8, 95, 0, 420, false),
  (231, 'Chermoula Salad', 'North African', 'middle_eastern', 'vegan', false, 'salad', '2', '15 min', '0 min', 'A vibrant salad dressed in chermoula — Morocco''s signature herb and spice marinade of coriander, cumin and lemon — tossed with roasted vegetables.', 'Chermoula is better when the vegetables are still warm — the heat opens the surface and allows the marinade to soak in rather than just sitting on top.', 'Traditional', NULL, ARRAY['2 courgettes, grilled or roasted','2 carrots, roasted','1 red pepper, roasted and peeled','For chermoula: 1 bunch coriander, 4 garlic cloves, 1 tsp cumin, 1 tsp paprika, 1/2 tsp chilli, juice of 1 lemon, 4 tbsp olive oil']::text[], ARRAY['Blend chermoula ingredients to a coarse, herb-flecked paste; season with salt.','Slice roasted vegetables and arrange on a platter.','Spoon chermoula generously over while vegetables are still warm.','Rest 10 min for the dressing to penetrate.','Serve at room temperature with crusty bread.']::text[], ARRAY['lunch']::text[], 'bowl', 150, 200, 3.2, 18.5, 15.8, 4.2, 1.8, 68, 0, 42, false),
  (232, 'Bastilla au Légumes (Vegetable Pastry Pie)', 'North African', 'middle_eastern', 'egg', false, 'main', '4', '30 min', '40 min', 'A Moroccan filo pie layered with almonds, spiced vegetables and scrambled egg, dusted with cinnamon and icing sugar — savoury and sweet in one dramatic dish.', 'The sweet-savoury contrast of icing sugar and cinnamon on top is not decorative — it is essential to bastilla''s flavour identity.', 'Traditional', NULL, ARRAY['8 sheets warqa or filo pastry','1 cup almonds, blanched and fried','2 courgettes and 1 carrot, diced and cooked','2 eggs, lightly beaten','1 onion, finely sliced','1/2 tsp cinnamon, 1/4 tsp ginger, 1/4 tsp pepper','2 tbsp chopped parsley and coriander','Butter for brushing','Icing sugar and cinnamon to dust top']::text[], ARRAY['Fry onion; add vegetables and spices; cook until dry; season.','Scramble eggs gently into the vegetable mix; cool.','Line a round tin with buttered filo sheets, overlapping; fill with almond layer then vegetable layer.','Fold overhanging pastry over; top with two more buttered sheets.','Bake 30 min at 190°C until golden; invert; dust with icing sugar and cinnamon pattern.']::text[], ARRAY['dinner']::text[], 'serving', 200, 360, 12.5, 28, 18.5, 3.2, 2.8, 85, 0.15, 180, false),
  (233, 'Loubia Tagine with Preserved Lemon', 'North African', 'middle_eastern', 'vegan', false, 'curry', '2', '10 min', '35 min', 'Green beans simmered in a fragrant tomato and preserved lemon tagine sauce — the everyday Moroccan vegetable dish at its most straightforward.', 'Moroccan tagine vegetables are intentionally cooked until very soft — al dente is not the goal here; tenderness and flavour absorption are.', 'Traditional', NULL, ARRAY['400g green beans or runner beans, trimmed','2 tomatoes, diced','1 onion, diced','3 garlic cloves, minced','1/2 preserved lemon, flesh removed and rind finely diced','1 tsp paprika','1/2 tsp cumin','1/2 tsp turmeric','3 tbsp olive oil','Fresh parsley and coriander']::text[], ARRAY['Saute onion in oil until soft; add garlic and spices; fry 1 min.','Add tomatoes and preserved lemon; cook 5 min until tomatoes break down.','Add beans and 1/2 cup water; cover and simmer 20-25 min until beans are very tender.','The sauce should be thick and coating; uncover last 5 min if too watery.','Scatter herbs; drizzle raw olive oil; serve warm or at room temperature.']::text[], ARRAY['dinner']::text[], 'bowl', 200, 280, 8.2, 22.5, 11.8, 5.6, 2.1, 68, 0, 385, false),
  (234, 'Briouats (Fried Filo Triangles)', 'North African', 'middle_eastern', 'veg', true, 'snack', '4', '30 min', '15 min', 'Crispy triangular filo pastries stuffed with a fragrant almond, honey and cinnamon filling — a Moroccan celebratory sweet that is impossible to eat just one of.', 'Seal the edges with melted butter as you fold — any opening will cause the triangles to burst and fill the oil with almonds.', 'Traditional', NULL, ARRAY['8 sheets filo pastry, cut into strips','1 cup ground almonds','3 tbsp honey','1 tsp orange blossom water','1 tsp cinnamon','Pinch of ginger','2 tbsp butter, melted','Oil for deep frying','Extra honey and sesame seeds to finish']::text[], ARRAY['Mix ground almonds with honey, orange blossom water, cinnamon and ginger to a paste.','Place a teaspoon of filling at the base of a filo strip; fold into a triangle, sealing with melted butter; repeat.','Deep fry at 170°C until golden — 2-3 min; drain.','While hot, drizzle with honey and scatter sesame seeds.','Serve warm or at room temperature; store in an airtight tin.']::text[], ARRAY['snack']::text[], 'piece', 40, 210, 6.2, 18.5, 12.8, 2.1, 1.4, 68, 0.08, 95, false),
  (235, 'Khobz (Moroccan Round Bread)', 'North African', 'middle_eastern', 'vegan', true, 'staple', '4', '20 min', '25 min', 'Morocco''s everyday round, slightly domed bread — baked in a communal oven or home oven until the crust is golden and the crumb is soft and chewy.', 'The tap test is more reliable than timing — every oven differs, and a hollow sound tells you the bread is done even if the colour seems light.', 'Traditional', NULL, ARRAY['3 cups plain flour','1 tsp instant yeast','1 tsp salt','1 tsp sugar','1 tbsp olive oil','Warm water to combine (approx 200ml)','1 tbsp semolina for dusting']::text[], ARRAY['Combine flour, yeast, salt and sugar; add oil and enough warm water to form a smooth, elastic dough.','Knead 10 min; rest 1 hr until doubled.','Divide into two rounds; shape into flat discs; dust with semolina.','Rest 20 min; score tops with a knife.','Bake at 220°C for 20-25 min until golden; tap the base — it should sound hollow.']::text[], ARRAY['snack']::text[], 'piece', 80, 230, 7.2, 38.5, 3.8, 1.3, 2.1, 18, 0, 285, false),
  (236, 'Maakouda (Potato Fritter)', 'North African', 'middle_eastern', 'egg', false, 'snack', '3', '15 min', '20 min', 'Golden potato cakes flavoured with cumin, coriander and harissa, fried crisp on the outside — Tunisia''s beloved street fritter, eaten in a sandwich or alone.', 'Chilling the shaped patties before frying is important — cold potato holds together in the oil; warm potato breaks apart.', 'Traditional', NULL, ARRAY['4 large potatoes, boiled and mashed','1 egg','2 garlic cloves, minced','1 tsp cumin','1/2 tsp coriander','1 tbsp harissa','3 tbsp flat-leaf parsley, chopped','Salt and pepper','Oil for shallow frying']::text[], ARRAY['Combine mashed potato with egg, garlic, cumin, coriander, harissa, parsley, salt and pepper.','Shape into round patties about 1cm thick; refrigerate 10 min to firm.','Shallow fry in hot oil 3-4 min each side until deep golden.','Drain on paper; serve hot with harissa, olives or inside crusty bread.','They will hold their shape better if not touched for the first 2 min of frying.']::text[], ARRAY['snack']::text[], 'piece', 80, 190, 5.2, 18.5, 8.1, 1.8, 1.2, 32, 0.12, 285, false),
  (237, 'Kaab el Ghazal (Gazelle Horns)', 'North African', 'middle_eastern', 'veg', true, 'dessert', '6', '45 min', '15 min', 'Elegant crescent-shaped Moroccan cookies filled with almond paste and orange blossom — the pastry that has graced every Moroccan celebration table for centuries.', 'Kaab el ghazal should be pale — over-baking dries out the almond paste and loses the soft, marzipan-like interior that defines them.', 'Traditional', NULL, ARRAY['For pastry: 2 cups flour, 4 tbsp butter, pinch of salt, orange blossom water to bind','For filling: 2 cups ground almonds, 1/2 cup icing sugar, 1 tbsp orange blossom water, 1 tsp cinnamon, 1 tbsp butter','Icing sugar to dust']::text[], ARRAY['Mix almond filling ingredients to a smooth paste; form into thin finger-shaped logs.','Make pastry by rubbing butter into flour; add orange blossom water to form a pliable dough; rest 30 min.','Roll pastry thin; place almond log on one edge; roll to encase; seal and curve into a crescent.','Bake at 180°C for 12-15 min — they should be barely golden, not brown.','Cool; dust generously with icing sugar.']::text[], ARRAY['snack']::text[], 'piece', 35, 160, 4.2, 16.8, 8.5, 1.2, 1.1, 68, 0.08, 85, false),
  (238, 'Couscous with Seven Vegetables (Algerian)', 'North African', 'middle_eastern', 'vegan', false, 'main', '4', '20 min', '40 min', 'A magnificent Algerian couscous prepared with seven symbolic vegetables in a deep, saffron-spiced broth — a Friday dish and a festive one.', 'Steaming the couscous above the broth rather than just hydrating it with boiling water gives it an incomparably lighter texture.', 'Traditional', NULL, ARRAY['2 cups couscous, steamed','1 turnip, quartered','2 carrots, halved','1 courgette, chunked','1 cup pumpkin, cubed','1/2 head cabbage, wedged','1 cup chickpeas, cooked','1 onion','1 tsp ras el hanout, 1/4 tsp saffron, 1 tsp cinnamon','Olive oil and salt']::text[], ARRAY['Saute onion; add spices and saffron; stir 1 min.','Add all vegetables and chickpeas; cover with 1.5 litres water; simmer 30 min until all are tender.','Steam couscous above the broth if possible, adding butter and salt; fluff well.','Mound couscous on a wide platter; arrange vegetables on top.','Ladle broth over and serve the rest in a bowl on the side for people to add as they eat.']::text[], ARRAY['dinner']::text[], 'plate', 350, 410, 13.5, 62, 8.5, 10.2, 3.8, 92, 0, 385, false),
  (239, 'Mandazi (East African Doughnuts)', 'East African', 'african', 'egg', true, 'snack', '4', '20 min', '20 min', 'Lightly sweet, fluffy triangular doughnuts scented with cardamom and coconut — the classic East African tea-time bread, eaten from Mombasa to Nairobi.', 'Rolling the dough on the thicker side (1cm) gives mandazi the soft, pillowy interior that distinguishes them from a flat, tough fry-bread.', 'Traditional', NULL, ARRAY['2 cups self-raising flour','1/4 cup sugar','1/2 tsp cardamom','1/2 cup coconut milk','1 egg','Oil for deep frying']::text[], ARRAY['Combine flour, sugar and cardamom; whisk egg into coconut milk; mix into dry ingredients to form a soft dough.','Knead briefly; rest 15 min; roll to 1cm thickness.','Cut into triangles or circles.','Deep fry at 170°C in batches until puffed and golden — 3-4 min each side.','Drain on paper; eat warm with tea.']::text[], ARRAY['breakfast']::text[], 'piece', 60, 240, 4.2, 28.5, 10.8, 0.9, 1.4, 85, 0.15, 320, false),
  (240, 'Chapati with Spiced Beans', 'East African', 'african', 'vegan', false, 'main', '2', '20 min', '25 min', 'Soft, layered East African chapati alongside a tumble of spiced kidney beans — a filling, affordable breakfast found from Uganda to Tanzania.', 'The log-coiling technique is what gives East African chapati its flaky, multi-layered texture distinct from a simple flatbread.', 'Traditional', NULL, ARRAY['2 cups plain flour','1/2 tsp salt','Warm water to make a soft dough','3 tbsp vegetable oil for layering','For beans: 1 can kidney beans, 1 onion, 2 tomatoes, 1 tsp cumin, 1/2 tsp turmeric, coriander']::text[], ARRAY['Make chapati: mix flour and salt; add water and knead 5 min; rest 15 min.','Roll a ball thin; brush oil; roll up into a log; coil the log; flatten again — this creates layers.','Cook on a dry pan 2 min each side until flecked with brown.','For beans: fry onion; add tomatoes, cumin, turmeric; cook 10 min; add beans; simmer 10 min; scatter coriander.','Serve folded chapati with beans alongside.']::text[], ARRAY['breakfast']::text[], 'plate', 300, 370, 12.5, 48, 8.5, 6.8, 3.2, 45, 0, 385, false),
  (241, 'Uji (Fermented Grain Porridge)', 'East African', 'african', 'vegan', true, 'main', '2', '5 min', '15 min', 'A thin, lightly sour porridge of fermented maize or millet flour — Kenya and Tanzania''s traditional morning drink, energising and easy to digest.', 'Mix the flour with cold water first before adding to hot water — adding it dry creates lumps that are almost impossible to smooth out.', 'Traditional', NULL, ARRAY['1 cup fermented maize or millet flour (or regular flour with 1 tbsp yoghurt for tang)','4 cups water','1/4 tsp salt','Sugar to taste','Squeeze of lemon juice','Milk (optional, to enrich)']::text[], ARRAY['Mix flour to a smooth paste with 1 cup cold water; no lumps.','Bring remaining 3 cups water to a boil with salt.','Whisk in flour paste gradually, stirring constantly to prevent lumps.','Simmer on low heat 8-10 min, stirring frequently, until it thickens slightly and the raw flour taste disappears.','Sweeten; add lemon juice; serve warm in a cup or bowl; stir in milk if desired.']::text[], ARRAY['breakfast']::text[], 'bowl', 250, 220, 3.2, 48.5, 0.8, 2.1, 1.2, 28, 0.05, 290, false),
  (242, 'Injera with Teff Porridge (Genfo)', 'East African', 'african', 'veg', true, 'staple', '2', '5 min', '20 min', 'Thick Ethiopian teff flour porridge (genfo) served with a well of spiced butter and berbere chilli — a warming, nourishing highland breakfast.', 'Cook genfo until it is genuinely thick and pulls from the sides — undercooked genfo is gluey and raw-tasting.', 'Traditional', NULL, ARRAY['1 cup teff flour','3 cups water','1/2 tsp salt','2 tbsp spiced Ethiopian butter (niter kibbeh) or plain butter','1 tsp berbere spice mix','Plain yoghurt to serve']::text[], ARRAY['Bring water to a boil; gradually whisk in teff flour, stirring constantly.','Cook on low heat 10-15 min, stirring frequently with a wooden paddle, until very thick and pulling away from the sides.','The texture should be like very stiff polenta.','Mound into a bowl; make a well in the centre; spoon butter into the well; dust berbere over the butter.','Serve with plain yoghurt on the side to balance the heat.']::text[], ARRAY['breakfast']::text[], 'bowl', 250, 310, 8.5, 48.2, 8.9, 6.8, 5.2, 95, 0.1, 420, false),
  (243, 'Timatim Salad (Ethiopian Tomato Salad)', 'East African', 'african', 'vegan', false, 'salad', '2', '10 min', '0 min', 'A refreshing Ethiopian salad of ripe tomatoes, red onion, jalapeño and coriander dressed with oil and lemon — simple, fresh and essential alongside injera.', 'Draining the tomatoes briefly prevents the salad from becoming watery in the serving bowl — especially important if it sits for more than a few minutes.', 'Traditional', NULL, ARRAY['4 ripe tomatoes, diced','1/2 red onion, very finely diced','1-2 jalapeños or green chillies, minced','1/4 cup fresh coriander, roughly chopped','2 tbsp olive oil','Juice of 1 lemon','1/2 tsp salt','Pinch of black pepper']::text[], ARRAY['Dice tomatoes and drain briefly in a colander to remove excess juice.','Combine tomatoes with onion, jalapeño and coriander.','Dress with olive oil, lemon juice, salt and pepper.','Toss gently; taste and adjust.','Serve immediately alongside injera or rice — it is a condiment as much as a salad.']::text[], ARRAY['lunch']::text[], 'bowl', 120, 120, 1.8, 8.2, 7.5, 1.6, 0.4, 18, 0, 290, false),
  (244, 'Ugali with Sukuma Wiki', 'East African', 'african', 'vegan', false, 'staple', '2', '5 min', '25 min', 'Kenya''s national dish — a dense, stiff maize porridge (ugali) served with braised collard greens (sukuma wiki) — the everyday meal of millions.', 'Ugali should hold a firm shape when scooped — if it flows or sags, cook longer; the correct texture lets you roll a ball without sticking to your palm.', 'Traditional', NULL, ARRAY['2 cups maize flour (ugali flour or fine polenta)','4 cups water','Salt to taste','For sukuma wiki: 1 large bunch collard greens, shredded','1 onion, sliced','2 tomatoes, diced','1 tsp cumin','2 tbsp vegetable oil']::text[], ARRAY['Bring water and salt to a boil; gradually pour in maize flour, stirring vigorously.','Cook on low heat 15-20 min, stirring constantly with a wooden spoon, until it pulls from the sides and holds its shape.','For sukuma: saute onion in oil; add tomatoes and cumin; cook 5 min; add greens and a splash of water; cook 8 min.','Shape ugali into a dome on a plate or board.','Serve sukuma alongside — tear and scoop the ugali with your right hand.']::text[], ARRAY['lunch']::text[], 'plate', 300, 350, 8.5, 52, 9.5, 4.2, 2.8, 95, 0, 320, false),
  (245, 'Githeri (Maize and Bean Stew)', 'East African', 'african', 'vegan', false, 'main', '3', '10 min', '40 min', 'Kenya''s ancestral dish of boiled maize and kidney beans slow-simmered with onion, tomato and spices — humble, nourishing and deeply comforting.', 'The beans and maize should be fully cooked separately before combining — trying to cook them together from raw results in uneven textures.', 'Traditional', NULL, ARRAY['1 cup dried kidney beans, soaked and cooked','1 cup dried maize or canned hominy','1 onion, diced','2 tomatoes, diced','1 carrot, diced','1 tsp curry powder','1 tsp cumin','2 tbsp vegetable oil','Salt and pepper','Coriander to garnish']::text[], ARRAY['Saute onion in oil until golden; add carrot and cook 3 min.','Add tomatoes, curry powder and cumin; cook 5 min.','Add cooked beans and maize; stir to combine.','Add 1 cup water; simmer 25 min until thick and stew-like.','Season; scatter coriander; serve with ugali or chapati.']::text[], ARRAY['lunch']::text[], 'bowl', 300, 340, 12.5, 42, 8.5, 8.2, 3.8, 65, 0, 380, false),
  (246, 'Red Lentil and Vegetable Stew (Misir Wat)', 'East African', 'african', 'veg', false, 'dal', '2', '10 min', '30 min', 'Ethiopian berbere-spiced red lentil stew — a pillar of the injera plate, deeply flavoured and deeply satisfying in its simplicity.', 'Dry-caramelising the onion without oil is the defining technique of misir wat — it builds a depth of flavour that oil-fried onion cannot replicate.', 'Traditional', NULL, ARRAY['1 cup red lentils, rinsed','1 large onion, finely chopped','4 garlic cloves, minced','1 tsp fresh ginger, grated','2 tbsp berbere spice mix','2 tbsp niter kibbeh (spiced butter) or plain butter','2 cups water or stock','Salt to taste']::text[], ARRAY['Dry-fry onion on low heat without oil for 15 min, stirring, until very dark and caramelised — this is the key step.','Add spiced butter, garlic, ginger and berbere; fry 2 min.','Add lentils and water; bring to a boil; simmer 15-20 min until lentils are fully dissolved.','Stir well — the stew should be thick and almost spreadable.','Serve on injera or rice.']::text[], ARRAY['dinner']::text[], 'bowl', 200, 280, 18.5, 38.2, 8.4, 6.8, 4.2, 52, 0.1, 385, false),
  (247, 'Irio (Kenyan Mashed Peas and Corn)', 'East African', 'african', 'veg', false, 'staple', '2', '10 min', '25 min', 'A Kikuyu staple of mashed potato, peas and corn blended together — dense, green-flecked and deeply comforting, often served with a side stew.', 'Do not over-mash irio — the chunky texture with visible pieces of pea and corn is what makes it irio rather than plain mashed potato.', 'Traditional', NULL, ARRAY['3 large potatoes, peeled and cubed','1 cup frozen peas','1 cup sweet corn kernels','1 tbsp butter','Salt and black pepper to taste']::text[], ARRAY['Boil potatoes in salted water until very tender; add peas and corn last 5 min.','Drain, reserving a cup of cooking water.','Mash roughly with butter, adding cooking water to reach a thick, chunky texture.','The peas should turn the mash slightly green — this is characteristic.','Season well; serve mounded as a side to stews or grilled vegetables.']::text[], ARRAY['dinner']::text[], 'bowl', 220, 300, 8.5, 42, 7.5, 6.2, 1.8, 45, 0.08, 85, false),
  (248, 'Vegetable Pilau (East African)', 'East African', 'african', 'vegan', false, 'main', '2', '15 min', '30 min', 'Basmati rice cooked with whole spices, onion and mixed vegetables — the celebratory rice of the East African coast, perfumed with cinnamon and cardamom.', 'Deeply golden onions (almost burnt) are the authentic flavour base of East African pilau — pale onions produce a bland, flat-tasting dish.', 'Traditional', NULL, ARRAY['1.5 cups basmati rice','2 medium potatoes, cubed','1 carrot, diced','1 cup green peas','1 onion, sliced','2 garlic cloves, 1 tsp fresh ginger','1 cinnamon stick','4 cardamom pods','4 cloves','1 tsp pilau masala spice mix','2 tbsp oil','2.5 cups vegetable stock','Salt']::text[], ARRAY['Fry onion in oil until deeply golden; add garlic, ginger and whole spices; fry 1 min.','Add pilau masala; fry 30 seconds; add potato and carrot.','Pour in stock and bring to a boil; add rice, peas and salt.','Cover tightly; cook on the lowest heat 15 min; do not lift the lid.','Rest 5 min; fluff gently; serve with kachumbari on the side.']::text[], ARRAY['dinner']::text[], 'plate', 300, 380, 8.5, 52, 12.5, 4.8, 2.1, 45, 0, 420, false),
  (249, 'Kachumbari (East African Fresh Salad)', 'East African', 'african', 'vegan', false, 'salad', '2', '10 min', '0 min', 'Diced tomato, red onion and coriander in a sharp lime dressing — the ubiquitous East African fresh salad that accompanies almost every meal.', 'Rinsing the raw onion under cold water removes the harsh sulfur compounds and makes the flavour clean and mild without losing the crunch.', 'Traditional', NULL, ARRAY['3 tomatoes, diced','1/2 red onion, very finely diced','1/2 cucumber, diced','1-2 green chillies, minced','1/4 cup fresh coriander, chopped','Juice of 1.5 limes','1 tbsp olive oil','Salt and black pepper']::text[], ARRAY['Dice tomatoes; dice onion small — rinse diced onion in cold water and squeeze dry to mellow its sharpness.','Combine tomato, cucumber, onion, chilli and coriander.','Dress with lime juice, olive oil, salt and pepper.','Taste; adjust lime and salt.','Serve immediately — it is at its best fresh.']::text[], ARRAY['lunch']::text[], 'bowl', 120, 90, 1.8, 8.5, 7.2, 1.9, 0.6, 32, 0, 285, false),
  (250, 'East African Samosa', 'East African', 'african', 'vegan', false, 'snack', '4', '30 min', '20 min', 'Crisp, golden pastry triangles filled with a spiced potato and pea mixture — the East African samosa, found at every tea stall from Nairobi to Dar es Salaam.', 'A stiff pastry dough (less water) is essential — too soft and the samosa will burst in the oil; too thick and it stays pale and doughy inside.', 'Traditional', NULL, ARRAY['For pastry: 2 cups flour, 1/2 tsp salt, 1 tbsp oil, warm water to bind','For filling: 3 potatoes (boiled and diced), 1/2 cup peas, 1 onion (finely diced), 1 tsp curry powder, 1/2 tsp cumin, salt, fresh coriander','Oil for deep frying']::text[], ARRAY['Make pastry: mix flour, salt and oil; add warm water to form a stiff, smooth dough; rest 20 min.','Fry onion; add spices; add potato and peas; cook 3 min; season; cool.','Roll pastry thin; cut into strips; fold each strip into a cone; fill; seal the top.','Deep fry at 175°C until golden — 3-4 min.','Drain; serve hot with tamarind chutney.']::text[], ARRAY['snack']::text[], 'piece', 60, 210, 5.2, 24.8, 7.1, 2.9, 1.8, 28, 0, 385, false),
  (251, 'Mahamri (Swahili Coconut Doughnut)', 'East African', 'african', 'vegan', true, 'snack', '4', '20 min', '15 min', 'Slightly sweet, yeasted coconut milk doughnuts from the Swahili coast — softer and richer than mandazi, with a characteristic diamond shape.', 'Mahamri must fry at a lower temperature than mandazi — the higher sugar content burns quickly on high heat before the interior is cooked.', 'Traditional', NULL, ARRAY['2 cups plain flour','1/2 tsp instant yeast','3 tbsp sugar','1/2 tsp cardamom','1/2 cup coconut milk','Warm water to mix (approx 80ml)','Oil for deep frying']::text[], ARRAY['Combine flour, yeast, sugar and cardamom; add coconut milk and enough warm water to form a soft dough.','Knead until smooth; rest 1 hour until puffy.','Roll to 1cm thickness; cut into diamond shapes.','Fry at 165°C until golden and cooked through — 4-5 min each side on low heat.','Drain; eat warm with tea.']::text[], ARRAY['snack']::text[], 'piece', 55, 230, 3.2, 28.5, 10.8, 0.9, 1.2, 18, 0, 95, false),
  (252, 'Viazi Karai (Spiced Fried Potato)', 'East African', 'african', 'vegan', false, 'snack', '3', '10 min', '20 min', 'Potato chunks dipped in a spiced gram flour batter and deep fried until golden — a Zanzibari street food eaten with tamarind chutney.', 'Boil the potatoes through before battering — raw potato inside a cooked batter is the most common mistake with viazi karai.', 'Traditional', NULL, ARRAY['3 medium potatoes, boiled and quartered','For batter: 1 cup gram flour (chickpea flour), 1 tsp cumin, 1/2 tsp turmeric, 1/2 tsp chilli powder, salt, water to form a thick batter','Oil for deep frying','Tamarind chutney and lime to serve']::text[], ARRAY['Mix gram flour with spices and enough water to make a thick, coating batter.','Dip boiled potato pieces in batter to coat fully.','Deep fry at 175°C until the batter is golden and crisp — 3-4 min.','Drain on paper; serve immediately — they lose their crispness quickly.','Squeeze lime; serve with tamarind chutney.']::text[], ARRAY['snack']::text[], 'serving', 120, 200, 6.8, 22.5, 8.2, 3.1, 2.4, 48, 0, 280, false),
  (253, 'Bhajia (Kenyan Potato Bhajia)', 'East African', 'african', 'vegan', false, 'snack', '3', '15 min', '20 min', 'Thin slices of potato coated in a spiced gram flour batter and fried crisp — the Kenyan coastal bhajia, lighter and more delicate than the Indian version.', 'Thin, even potato slices — use a mandoline if you have one — are what give Kenyan bhajia their characteristic delicacy.', 'Traditional', NULL, ARRAY['4 medium potatoes, thinly sliced (not peeled)','1 cup gram flour','1/2 tsp turmeric','1 tsp cumin seeds','1/2 tsp chilli powder','1/2 tsp garlic powder','Handful of fresh coriander, minced','Salt','Water to make batter','Oil for deep frying']::text[], ARRAY['Combine gram flour, spices, coriander and salt; whisk in water until a thin, coating batter forms.','Dip each potato slice; allow excess to drip off.','Fry in hot oil at 175°C in small batches until golden and crisp — 2-3 min.','Do not overcrowd the pan — bhajia must float freely to crisp evenly.','Drain; serve hot with green chutney.']::text[], ARRAY['snack']::text[], 'serving', 100, 190, 5.2, 22.8, 8.1, 2.4, 1.8, 28, 0, 185, false),
  (254, 'Açaí Bowl', 'South American', 'latin_american', 'veg', true, 'main', '1', '10 min', '0 min', 'A Brazilian icon — frozen açaí blended thick and topped with granola, banana, honey and coconut — the Amazon in a bowl.', 'Keep the liquid to an absolute minimum — an açaí bowl should be thick enough to support toppings, not a smoothie that soaks them.', 'Traditional', NULL, ARRAY['200g frozen açaí pulp (unsweetened)','1 frozen banana','2 tbsp almond or oat milk','Toppings: 3 tbsp granola, 1/2 banana sliced, 1 tbsp honey, 1 tbsp shredded coconut, fresh berries, 1 tsp chia seeds']::text[], ARRAY['Blend frozen açaí pulp with frozen banana and milk — start with minimum liquid to keep thick.','Blend until smooth but still thick enough to eat with a spoon; it should not pour.','Pour into a chilled bowl.','Arrange toppings in rows: granola, banana, berries, coconut, chia.','Drizzle honey; serve immediately before it melts.']::text[], ARRAY['breakfast']::text[], 'bowl', 350, 380, 9.2, 52.8, 12.4, 8.6, 2.1, 156, 0.3, 94, false),
  (255, 'Tapioca Crepe with Coconut and Banana', 'South American', 'latin_american', 'veg', true, 'staple', '2', '10 min', '10 min', 'Gluten-free tapioca starch crepes with a sweet coconut and banana filling — Brazil''s north-eastern tapioca, unique and simple.', 'Tapioca crepes set and stiffen within seconds of being removed from the pan — fill and fold while still in the pan over heat.', 'Traditional', NULL, ARRAY['1 cup tapioca starch (hydrated)','Pinch of salt','For filling: 1 banana, sliced','3 tbsp desiccated coconut','1 tbsp honey or condensed milk','Butter to grease pan']::text[], ARRAY['Hydrate tapioca starch with a little water until it holds when squeezed; it should be crumbly but moist.','Press through a fine sieve to form a dry, even layer in a non-stick pan over medium heat.','Cook 2 min until the surface sets and the edges begin to lift; flip carefully.','Immediately lay banana and coconut on one half; fold over.','Drizzle honey; eat while the outside is still crisp.']::text[], ARRAY['breakfast']::text[], 'piece', 150, 290, 2.8, 48.5, 9.2, 1.8, 0.4, 22, 0.05, 95, false),
  (256, 'Changua (Colombian Milk Soup with Egg)', 'South American', 'latin_american', 'egg', false, 'soup', '2', '5 min', '15 min', 'A Colombian Andean highland soup of warm milk, poached egg and stale bread — the gentle, warming breakfast of Bogotá and the surrounding highlands.', 'A gentle simmer — not a boil — keeps the egg white tender; a rolling boil shreds the white before it sets.', 'Traditional', NULL, ARRAY['2 cups whole milk','1 cup water','2 eggs','2 spring onions (scallions), sliced','Fresh coriander, chopped','2 slices stale bread or toast, cubed','Salt to taste','Butter (optional)']::text[], ARRAY['Bring milk and water to a gentle simmer with spring onion, salt and a little butter.','Crack eggs directly into the simmering milk; poach 4-5 min until whites are set.','Place cubed bread in the bottom of each bowl.','Carefully ladle the milk soup and an egg into each bowl.','Scatter coriander; add more spring onion; serve with extra toast.']::text[], ARRAY['breakfast']::text[], 'bowl', 250, 250, 12.5, 18.2, 9.8, 0.6, 1.8, 320, 0.8, 385, false),
  (257, 'Calentado (Colombian Leftover Breakfast)', 'South American', 'latin_american', 'egg', false, 'main', '2', '5 min', '15 min', 'Leftover rice and red beans fried with egg and plantain — the beloved Colombian Monday morning breakfast built from Sunday''s supper.', 'The slight crisping of the rice and beans in the pan — not just reheating — is what makes calentado a proper dish rather than warmed leftovers.', 'Traditional', NULL, ARRAY['1 cup cooked white rice','1 cup cooked red beans with their sauce','2 eggs','1 ripe plantain, sliced into rounds','2 tbsp vegetable oil','Salt and pepper','Fresh coriander','Hot sauce to serve']::text[], ARRAY['Fry plantain slices in oil until golden on both sides; set aside.','In the same pan, fry rice and beans together, tossing until heated through and slightly crisped.','Push to one side; fry eggs sunny side up in the same pan.','Plate rice-and-beans; add egg on top; arrange plantain alongside.','Scatter coriander; add hot sauce.']::text[], ARRAY['breakfast']::text[], 'plate', 350, 400, 14.5, 48.2, 14.8, 5.6, 3.2, 68, 0.5, 420, false),
  (258, 'Locro de Papa (Ecuadorian Potato Soup)', 'South American', 'latin_american', 'veg', false, 'soup', '3', '10 min', '30 min', 'A thick, milky Ecuadorian potato soup made creamy with melted white cheese and finished with avocado — the Andean highlands in a bowl.', 'The cheese should melt softly into the broth, not fully dissolve — semi-firm white cheese (not mature cheddar) is what achieves this.', 'Traditional', NULL, ARRAY['5 medium potatoes, diced (waxy variety)','1 onion, diced','3 garlic cloves, minced','1/2 tsp achiote or paprika','1 cup milk','100g white cheese (or feta), cubed','1 cup vegetable stock','2 tbsp vegetable oil','Salt and cumin to taste','Avocado slices and coriander to serve']::text[], ARRAY['Saute onion with achiote in oil until orange and fragrant; add garlic.','Add potato and stock; simmer 20 min until potato is very soft.','Mash some potato directly in the pot to thicken; add milk and stir.','Add cubed cheese; stir gently — it should melt into creamy pockets.','Ladle into bowls; top with avocado and coriander; serve with bread.']::text[], ARRAY['lunch']::text[], 'bowl', 300, 310, 10.5, 32, 11.5, 2.8, 1.2, 185, 0.4, 420, false),
  (259, 'Sopa de Quinoa (Andean Quinoa Soup)', 'South American', 'latin_american', 'vegan', false, 'soup', '2', '10 min', '25 min', 'Quinoa simmered in a vegetable broth with potato, carrot and Andean herbs — the ancient grain of the Incas in its most traditional soup form.', 'Quinoa must be thoroughly rinsed before cooking to remove saponins — without rinsing the soup will have a bitter, soapy edge.', 'Traditional', NULL, ARRAY['1/2 cup white quinoa, rinsed','2 medium potatoes, diced','1 carrot, diced','1 stalk celery, diced','1 onion, diced','3 garlic cloves, minced','1 litre vegetable stock','1 tsp cumin','Fresh coriander and flat-leaf parsley','Salt, pepper and lime to serve']::text[], ARRAY['Saute onion and garlic in oil; add cumin; cook 1 min.','Add carrot, celery and potato; stir.','Add stock; bring to a boil; add rinsed quinoa.','Simmer 20 min until quinoa is cooked (white tails will have unfurled) and potato is tender.','Season; scatter herbs; squeeze lime; serve hot.']::text[], ARRAY['lunch']::text[], 'bowl', 300, 270, 8.5, 48.2, 3.1, 6.8, 4.2, 62, 0, 420, false),
  (260, 'Causa Limeña (Peruvian Potato Terrine)', 'South American', 'latin_american', 'vegan', false, 'side', '2', '30 min', '0 min', 'Cold, layered potato terrine filled with avocado and vegetables — Lima''s most elegant street food, as beautiful to look at as it is to eat.', 'The potato must be mashed while hot and mixed with oil while warm — cold potato mixed with oil turns grainy and will not hold together.', 'Traditional', NULL, ARRAY['4 yellow potatoes, boiled and mashed hot','2 tbsp aji amarillo paste (or 1 tbsp mild chilli paste)','Juice of 2 limes','3 tbsp vegetable oil','Salt to taste','For filling: 2 avocados, sliced','2 tomatoes, diced','Lime, salt, pepper']::text[], ARRAY['Mix hot mashed potato with aji amarillo, lime juice, oil and salt until smooth and bright yellow; cool to room temperature.','Season avocado and tomato separately with lime, salt and pepper.','Press half the potato into a rectangular mould or loaf tin; layer avocado and tomato on top; press remaining potato over to cover.','Refrigerate 30 min to firm.','Unmould; slice and serve cold garnished with olives and boiled egg.']::text[], ARRAY['lunch']::text[], 'serving', 200, 290, 4.2, 28.5, 16.8, 5.1, 1.2, 32, 0, 280, false),
  (261, 'Chupe de Verduras (Andean Vegetable Chowder)', 'South American', 'latin_american', 'veg', false, 'soup', '3', '15 min', '30 min', 'A rich Andean vegetable and quinoa chowder with milk and fresh cheese — the warming soup of the highlands, thickened with potato and brightened with fresh herbs.', 'Add milk and cheese off or on lowest heat only — boiling after adding dairy splits the milk and makes the chowder grainy.', 'Traditional', NULL, ARRAY['2 potatoes, diced','1/2 cup quinoa, rinsed','1 courgette, diced','1 ear of corn, kernels cut off','1 cup milk','100g fresh white cheese, cubed','1 onion, diced','3 garlic cloves','1 tsp cumin','1 litre vegetable stock','Oil, salt, pepper','Fresh mint and coriander']::text[], ARRAY['Saute onion and garlic; add cumin; add potato and stock; simmer 10 min.','Add quinoa, courgette and corn; simmer 15 min until quinoa is cooked.','Stir in milk; bring gently to a simmer; add cheese; stir until just melted.','Season; taste; adjust.','Serve in deep bowls; scatter fresh mint and coriander on top.']::text[], ARRAY['dinner']::text[], 'bowl', 350, 350, 14.2, 42.8, 10.5, 6.2, 2.1, 185, 0.4, 520, false),
  (262, 'Tofu Picante Salteado (Spicy Stir-Fried Tofu)', 'South American', 'latin_american', 'vegan', false, 'main', '2', '15 min', '15 min', 'Tofu and vegetables stir-fried in the Peruvian lomo saltado style — soy sauce, tomatoes and aji amarillo over white rice and chips.', 'Lomo saltado is a high-heat, quick-cook dish — a pan that is not ripping hot will steam the ingredients rather than char them.', 'Traditional', NULL, ARRAY['300g firm tofu, pressed and cubed','2 tomatoes, cut into wedges','1 red onion, cut into wedges','2 tbsp soy sauce','1 tbsp aji amarillo paste','1 tsp cumin','2 garlic cloves, minced','2 tbsp vegetable oil','Coriander, lime','Steamed rice and fries to serve']::text[], ARRAY['Press tofu; cut into cubes; fry in hot oil until golden on all sides; remove.','In the same pan on very high heat, fry onion and garlic 1 min — the pan must be smoking.','Add tomatoes; toss 1 min.','Add soy sauce, aji amarillo and cumin; toss; return tofu.','Serve immediately over rice; add fries; scatter coriander; squeeze lime.']::text[], ARRAY['dinner']::text[], 'plate', 250, 310, 15.2, 18.5, 12.8, 3.2, 2.4, 145, 0, 520, false),
  (263, 'Aji de Verduras (Vegetable Aji Stew)', 'South American', 'latin_american', 'veg', false, 'curry', '2', '15 min', '30 min', 'Yellow potato and mixed vegetables simmered in a creamy aji amarillo and bread-thickened sauce — a vegetarian adaptation of Peru''s iconic aji de gallina.', 'Soaking the bread in milk before blending is what gives aji sauce its characteristic thick, creamy, velvety body.', 'Traditional', NULL, ARRAY['3 yellow potatoes, boiled and halved','2 courgettes, sliced','1 carrot, sliced','For sauce: 3 aji amarillo chillies (or paste), 2 slices white bread (soaked in milk), 1 onion, 2 garlic cloves, 1/4 cup walnuts, 1/2 cup milk','Parmesan and black olives to garnish','Salt and oil']::text[], ARRAY['Blend soaked bread, aji amarillo, walnuts, garlic and milk until smooth.','Fry onion in oil until soft; add blended sauce; stir and cook 5 min.','Add courgettes and carrot; cook 8 min.','Add boiled potato halves; coat everything in the sauce; simmer 5 min more.','Serve garnished with parmesan, olives and egg.']::text[], ARRAY['dinner']::text[], 'bowl', 300, 290, 12.5, 32.8, 10.2, 5.1, 2.8, 185, 0.4, 385, false),
  (264, 'Sopa Paraguaya (Cornbread Casserole)', 'South American', 'latin_american', 'egg', false, 'snack', '6', '15 min', '40 min', 'Despite its name (''Paraguayan soup'') this is a dense, moist cornbread baked with cheese and onion — Paraguay''s national dish and a staple at every meal.', 'Sopa paraguaya is done when a skewer comes out clean and the top is uniformly golden — an underbaked sopa will collapse when cut.', 'Traditional', NULL, ARRAY['2 cups fine cornmeal (masa)','1 cup cottage cheese or fresh white cheese','1 onion, finely diced and sauteed','3 eggs','1/4 cup vegetable oil','1/2 cup milk','1 tsp salt','1 tsp baking powder']::text[], ARRAY['Saute onion in oil until soft and translucent; cool.','Beat eggs; mix with milk, oil, cottage cheese and salt.','Stir in cornmeal and baking powder; fold in sauteed onion.','Pour into a greased baking dish — batter should be thick.','Bake at 190°C for 35-40 min until set in the centre and golden on top.']::text[], ARRAY['snack']::text[], 'piece', 120, 280, 9.5, 28, 11, 1.8, 1.2, 145, 0.35, 420, false),
  (265, 'Tequeños (Venezuelan Cheese Bread Sticks)', 'South American', 'latin_american', 'egg', true, 'snack', '4', '20 min', '15 min', 'Twisted dough sticks wrapped around stretchy white cheese and fried golden — Venezuela''s most beloved party snack, impossible to stop at one.', 'Serve tequeños immediately — they are at their peak for about 4 minutes while the cheese is still liquid inside the crisp crust.', 'Traditional', NULL, ARRAY['2 cups plain flour','1/2 tsp salt','1 tbsp sugar','100g cold butter, cubed','1 egg','2 tbsp cold water','200g queso blanco or mozzarella, cut into sticks','Oil for deep frying']::text[], ARRAY['Rub butter into flour with salt and sugar until crumbly; add egg and water; mix to a dough; chill 15 min.','Roll out thin; cut into strips.','Wrap a strip tightly around each cheese stick, overlapping as you go; press ends to seal.','Deep fry at 175°C until golden — 3-4 min; do not overcook or cheese escapes.','Drain briefly; serve immediately while the cheese is still molten.']::text[], ARRAY['snack']::text[], 'serving', 80, 220, 8.5, 22, 11.2, 0.8, 1.1, 185, 0.28, 385, false),
  (266, 'Patacones (Twice-Fried Plantain)', 'South American', 'latin_american', 'vegan', true, 'snack', '2', '5 min', '15 min', 'Green plantain rounds fried, smashed flat and fried again until crispy — Colombia and Ecuador''s most addictive snack, eaten with everything.', 'Smash the plantains while still warm from the first fry — cold plantain cracks and shatters rather than pressing flat.', 'Traditional', NULL, ARRAY['2 green (unripe) plantains, peeled and sliced into 2cm rounds','Oil for deep frying','Salt','Guacamole or hogao (Colombian tomato sauce) to serve']::text[], ARRAY['Fry plantain rounds at 160°C for 4-5 min until cooked through but not coloured; drain.','While warm, smash each piece flat with a flat-bottomed glass or a tostonera.','Fry a second time at 185°C for 2-3 min until deeply golden and crisp.','Drain; salt immediately.','Serve with guacamole or hogao.']::text[], ARRAY['snack']::text[], 'serving', 100, 200, 1.2, 25.8, 9.1, 2.1, 0.4, 3.2, 0, 180, false),
  (267, 'Salteñas de Queso (Bolivian Cheese Pastries)', 'South American', 'latin_american', 'egg', false, 'snack', '6', '45 min', '25 min', 'Bolivian baked empanada-style pastries with a slightly sweet, juicy cheese and vegetable filling — the morning street food of La Paz.', 'The gelled filling is the secret to juicy salteñas — liquid filling at assembly time will leak; it must be solid cold and liquefy in the oven.', 'Traditional', NULL, ARRAY['For dough: 3 cups flour, 1/2 tsp salt, 2 tsp sugar, 100g butter, 2 eggs, 4 tbsp water','For filling: 200g white cheese (cubed), 1 potato (boiled and diced), 1/2 cup green olives, 2 tbsp parsley, 1 tsp aji amarillo paste, salt, gelatin stock to set (2 tbsp gelatin in 1 cup stock, cooled)']::text[], ARRAY['Make dough: rub butter into flour with salt and sugar; bind with egg and water; chill 30 min.','Mix cheese, potato, olives, parsley and aji paste into the cooled gelatin stock; chill until gelled — this creates a juicy filling.','Roll dough thin; cut circles; fill each with 2 tbsp filling; crimp edges shut.','Brush with egg wash; bake at 220°C for 20-25 min until deeply golden.','Eat while hot — the filling liquefies as it bakes.']::text[], ARRAY['snack']::text[], 'piece', 100, 250, 9.2, 28.5, 9.8, 1.2, 1.8, 185, 0.35, 520, false),
  (268, 'Koko (Spiced Millet Porridge)', 'West African', 'african', 'vegan', true, 'staple', '2', '5 min', '20 min', 'A Ghanaian and Burkinabé fermented millet porridge spiced with ginger and cloves — the warming breakfast sold by roadside vendors across West Africa at dawn.', 'Millet porridge thickens dramatically as it cools — serve immediately or keep over very low heat, adding water as needed.', 'Traditional', NULL, ARRAY['1 cup millet flour (or fermented millet for authenticity)','4 cups water','1 tsp ground ginger','1/2 tsp ground cloves','1/4 tsp black pepper','3 tbsp sugar or to taste','Pinch of salt','Koose (black-eyed pea fritters) to serve alongside']::text[], ARRAY['Mix millet flour to a smooth paste with 1 cup cold water.','Bring remaining 3 cups water to a boil.','Slowly whisk in the millet paste; stir constantly to prevent lumps.','Add ginger, cloves, pepper and salt; cook on medium-low heat 15 min, stirring frequently.','Sweeten; serve warm in bowls — eat with koose for the full street-food experience.']::text[], ARRAY['breakfast']::text[], 'bowl', 250, 230, 3.5, 48.2, 1.8, 2.1, 1.4, 18, 0, 95, false),
  (269, 'Tom Brown (Roasted Corn and Groundnut Porridge)', 'West African', 'african', 'vegan', true, 'staple', '2', '5 min', '15 min', 'A Ghanaian porridge of roasted and ground corn and groundnuts — rich, slightly smoky and deeply nourishing, often a child''s first solid food.', 'Whisking the paste into boiling water rather than adding cold water to cold paste gives a smoother, lump-free porridge every time.', 'Traditional', NULL, ARRAY['1 cup tom brown powder (or roast equal parts corn flour and ground peanuts in a dry pan)','4 cups water','3 tbsp sugar','Pinch of salt','1/2 tsp ground ginger (optional)','Milk to enrich (optional)']::text[], ARRAY['If making from scratch: dry-roast corn flour and ground peanuts separately until golden; combine equal parts.','Mix tom brown powder with 1 cup cold water to a smooth paste.','Bring 3 cups water to a boil; whisk in paste; stir constantly.','Cook 10-12 min on low heat, stirring, until thick and fully cooked.','Sweeten; add ginger; stir in milk if using; serve warm.']::text[], ARRAY['breakfast']::text[], 'bowl', 250, 310, 11.2, 34.8, 9.4, 3.2, 2.1, 45, 0, 85, false),
  (270, 'Masa (Fermented Rice Cakes)', 'West African', 'african', 'vegan', true, 'staple', '4', '8 hrs', '20 min', 'Fluffy Nigerian fermented rice cakes cooked in a special pan — eaten sweet with honey or savoury with pepper soup, they are the Northern Nigerian breakfast.', 'A takoyaki or aebleskiver pan creates the authentic round shape — without a dedicated pan, pour batter into oiled rings on a griddle instead.', 'Traditional', NULL, ARRAY['1 cup long-grain rice','1/4 cup cooked rice (for fermentation)','1/2 tsp instant yeast','1/2 tsp sugar','Pinch of salt','Warm water to blend','Oil for the masa pan or a takoyaki/aebleskiver pan']::text[], ARRAY['Soak raw rice overnight; blend with cooked rice, yeast, sugar, salt and enough water to form a thick pancake batter; ferment 4-6 hours.','Heat masa pan; grease each well generously.','Pour batter into each well; cook 3-4 min covered until the surface sets.','Flip each cake; cook 2 min on the other side.','Serve warm with honey, sugar or a side of pepper soup.']::text[], ARRAY['breakfast']::text[], 'serving', 100, 220, 3.8, 42.5, 2.1, 0.6, 0.4, 12, 0, 95, false),
  (271, 'Koose (Black-Eyed Pea Fritter)', 'West African', 'african', 'vegan', false, 'snack', '3', '4 hrs', '15 min', 'Fluffy, airy fritters of soaked and ground black-eyed peas spiced with pepper — Ghana''s breakfast fritter, fried in small rounds and eaten with koko.', 'Beating the batter vigorously before frying is the step that makes koose light and airy inside rather than dense and doughy.', 'Traditional', NULL, ARRAY['1 cup dried black-eyed peas, soaked overnight','1/2 onion','1-2 Scotch bonnet or habanero chillies (to taste)','1/2 tsp salt','Oil for deep frying']::text[], ARRAY['Drain soaked peas; rub vigorously between your palms to remove the skins; rinse away skins.','Blend deskinned peas with onion, chilli and salt using minimal water to a thick, fluffy paste.','Beat the paste vigorously with a wooden spoon for 3 min — this incorporates air.','Drop by tablespoon into hot oil; fry at 175°C until golden — 3-4 min.','Drain; serve hot alongside koko or tea.']::text[], ARRAY['breakfast']::text[], 'serving', 100, 200, 7.2, 22.1, 5.8, 4.2, 1.8, 45, 0, 385, false),
  (272, 'Waakye (Rice and Beans in Sorghum Leaves)', 'West African', 'african', 'vegan', false, 'main', '3', '10 min', '40 min', 'Ghanaian rice and black-eyed peas cooked together with dried sorghum leaves — which turn everything a deep reddish-brown — eaten with a feast of toppings.', 'The sorghum leaves are purely for colour and a subtle earthy flavour — if unavailable, a few dried red beans will tint the rice a similar reddish hue.', 'Traditional', NULL, ARRAY['1 cup long-grain rice','1 cup black-eyed peas, soaked','2-3 dried sorghum or millet leaves (for colour) or 1 tsp black food colouring','Salt to taste','Toppings: gari (cassava granules), shito (black pepper sauce), boiled egg, fried plantain, avocado']::text[], ARRAY['Boil black-eyed peas with sorghum leaves for 20 min; remove leaves.','Add rice; add water to cover 3cm above; salt; cook 20 min until both are fully tender and a brownish-red colour.','Meanwhile prepare toppings: fry plantain; boil eggs; warm shito sauce.','Pile waakye on a banana leaf or plate.','Add toppings to taste — the more varied, the better.']::text[], ARRAY['lunch']::text[], 'plate', 300, 390, 12.5, 58.2, 8.3, 5.8, 3.2, 42, 0.3, 285, false),
  (273, 'Kontomire Stew (Cocoyam Leaf Stew)', 'West African', 'african', 'vegan', false, 'curry', '2', '15 min', '30 min', 'A Ghanaian stew of cocoyam leaves (or spinach) cooked in palmnut cream with smoked spices and served over boiled yam — a deeply flavoured, nutritious staple.', 'Cocoyam leaves must be very finely chopped and cooked thoroughly — under-cooked leaves have an itchy texture from their oxalate content.', 'Traditional', NULL, ARRAY['300g cocoyam leaves or spinach, finely chopped','1 cup palmnut cream (or red palm oil broth)','1 onion, diced','3 garlic cloves','2 medium tomatoes','1 Scotch bonnet chilli','1 tsp ground crayfish (optional for depth)','Salt to taste','Boiled yam or plantain to serve']::text[], ARRAY['Blend tomatoes, onion, garlic and Scotch bonnet.','Heat palmnut cream; fry blended paste 8 min until oil rises.','Add finely chopped cocoyam leaves; stir; cook 10 min.','Add crayfish if using; season with salt.','Serve over boiled yam slices or with plantain.']::text[], ARRAY['dinner']::text[], 'bowl', 200, 280, 8.5, 18.2, 22.4, 4.1, 3.8, 185, 0.3, 380, false),
  (274, 'Vegetable Groundnut Soup', 'West African', 'african', 'vegan', false, 'soup', '3', '15 min', '35 min', 'A rich West African peanut soup with tomatoes, mixed vegetables and warming spices — thick, hearty and complex, served over rice or with fufu.', 'Whisk the peanut butter with warm stock first to form a smooth paste before adding to the pot — cold peanut butter added directly will lump.', 'Traditional', NULL, ARRAY['1 cup smooth natural peanut butter','2 tomatoes, diced','1 onion, diced','3 garlic cloves, minced','1 Scotch bonnet chilli','1 tsp ground ginger','1 litre vegetable stock','2 cups mixed vegetables (aubergine, spinach, sweet potato)','Salt to taste','Rice or fufu to serve']::text[], ARRAY['Fry onion and garlic; add tomatoes and Scotch bonnet; cook 8 min.','Whisk peanut butter into 1 cup warm stock until smooth; add to the pot.','Add remaining stock, ginger and all vegetables; stir; bring to a boil.','Simmer 20-25 min until vegetables are tender and soup is thick.','Season; serve over rice or with fufu.']::text[], ARRAY['dinner']::text[], 'bowl', 250, 380, 12.5, 18.2, 24.8, 3.6, 2.1, 68, 0, 520, false),
  (275, 'Okra Stew with Yam', 'West African', 'african', 'vegan', false, 'curry', '2', '10 min', '25 min', 'Sliced okra simmered in a tomato and pepper base to a thick, silky stew — eaten with boiled yam or pounded yam, a beloved comfort of the Nigerian kitchen.', 'Slice okra thinly (3-4mm) and do not overcook — the goal is a silky, slightly gelatinous stew, not a brown mush.', 'Traditional', NULL, ARRAY['300g fresh okra, thinly sliced','2 tomatoes, blended','1 onion, diced','2 garlic cloves','1 Scotch bonnet chilli','1 tsp ground crayfish (optional)','3 tbsp red palm oil or vegetable oil','Salt to taste','Boiled or pounded yam to serve']::text[], ARRAY['Heat palm oil; fry onion until softened; add garlic and Scotch bonnet; fry 1 min.','Add blended tomato; cook 10 min until thick and oil rises.','Add sliced okra and crayfish if using; stir gently.','Cook 8-10 min — the okra will release its natural thickener and the stew will become silky.','Season; serve with boiled yam.']::text[], ARRAY['dinner']::text[], 'bowl', 250, 340, 8.2, 28.5, 13.8, 5.2, 2.1, 148, 0.3, 245, false),
  (276, 'Bambara Groundnut Stew', 'West African', 'african', 'vegan', false, 'curry', '3', '10 min', '40 min', 'A West African peanut and bean stew from the Sahel — nutty, tomato-based and filling, eaten with rice across Mali, Senegal and Guinea.', 'This stew thickens significantly on standing — add extra stock to loosen when reheating.', 'Traditional', NULL, ARRAY['1 cup bambara groundnuts or black-eyed peas, cooked','1 cup smooth peanut butter','2 tomatoes, diced','1 onion, diced','2 garlic cloves','1 Scotch bonnet chilli','1 tsp smoked paprika','1 litre vegetable stock','Red palm oil','Salt and coriander']::text[], ARRAY['Fry onion in palm oil; add garlic and Scotch bonnet; add tomatoes; cook 8 min.','Whisk peanut butter in warm stock until smooth; add to pot.','Add cooked beans, paprika and remaining stock; stir.','Simmer 25 min until thick and rich; adjust consistency.','Season; scatter coriander; serve over white rice.']::text[], ARRAY['dinner']::text[], 'bowl', 250, 370, 18.5, 28.3, 18.2, 6.4, 3.8, 95, 0, 420, false),
  (277, 'Suya-Spiced Tofu with Yam', 'West African', 'african', 'vegan', false, 'main', '2', '20 min', '20 min', 'Firm tofu marinated in the smoky West African suya spice mix and grilled until charred, served with wedges of boiled yam — the plant-based suya experience.', 'Pressing the tofu dry before marinating is essential — wet tofu will not form a proper crust and the spice paste will steam off rather than char.', 'Traditional', NULL, ARRAY['300g firm tofu, pressed and sliced into steaks','For suya spice: 2 tbsp roasted groundnut powder, 1 tsp paprika, 1 tsp ginger, 1/2 tsp garlic powder, 1/2 tsp cayenne, 1/2 tsp onion powder, salt','1 tbsp vegetable oil','300g yam, boiled in salted water','Sliced onion and tomato to serve']::text[], ARRAY['Mix suya spice with oil to form a paste; press onto tofu steaks; marinate 15 min.','Grill or fry tofu in a hot, dry pan 4-5 min each side until deeply charred and crusted.','Boil yam until tender; slice.','Arrange tofu over yam slices.','Serve with raw onion rings and sliced tomato.']::text[], ARRAY['dinner']::text[], 'plate', 300, 340, 12.5, 38.2, 10.8, 5.4, 3.2, 145, 0, 480, false),
  (278, 'Plantain Stew with Black-Eyed Peas', 'West African', 'african', 'vegan', false, 'curry', '2', '10 min', '30 min', 'Ripe plantain simmered with black-eyed peas in a tomato and palm oil sauce — a sweet, savoury and satisfying Ghanaian main course.', 'Use ripe but not overripe plantain (yellow with black spots) — green plantain stays hard, while overripe plantain collapses completely into the sauce.', 'Traditional', NULL, ARRAY['2 ripe plantains, peeled and cut into chunks','1 cup black-eyed peas, cooked','2 tomatoes, blended','1 onion, diced','3 garlic cloves, minced','1 Scotch bonnet chilli','2 tbsp red palm oil','1 tsp ground coriander','Salt to taste','Fresh coriander to garnish']::text[], ARRAY['Heat palm oil; fry onion and garlic until soft; add blended tomato and Scotch bonnet; cook 10 min.','Add black-eyed peas and ground coriander; cook 5 min.','Add plantain chunks; stir gently — ripe plantain is delicate.','Add 1/2 cup water; cover and simmer 12-15 min until plantain is fully tender.','Season; scatter fresh coriander; serve with rice.']::text[], ARRAY['dinner']::text[], 'bowl', 250, 360, 8.5, 52, 12, 8.5, 2.8, 45, 0, 320, false),
  (279, 'Eba with Vegetable Ofe Onugbu', 'West African', 'african', 'vegan', false, 'main', '2', '10 min', '30 min', 'Smooth cassava flour dough (eba) served with a bitter leaf vegetable soup thick with palm oil and spices — a quintessential Nigerian meal.', 'Mix eba in a clean pot with a wooden spoon — it requires quick, vigorous stirring to prevent lumps and achieve the characteristic smooth, stretchy texture.', 'Traditional', NULL, ARRAY['1 cup cassava flour (garri), yellow or white','Boiling water to mix','For ofe onugbu: 1 bunch bitter leaf (washed) or spinach, 200g cocoyam powder (to thicken), palm oil, 1 onion, 2 stock cubes, Scotch bonnet, crayfish powder, salt']::text[], ARRAY['Boil 1 cup water per serving; pour garri in, stirring vigorously with a wooden spoon to form a smooth, stretchy dough; add more hot water if too stiff; rest 2 min.','For soup: heat palm oil; saute onion; add blended tomato and Scotch bonnet; cook 8 min.','Stir in dissolved cocoyam powder to thicken; add bitter leaf and crayfish; simmer 10 min.','Season; check thickness — ofe onugbu should coat a spoon.','Shape eba into a ball; serve with soup poured around.']::text[], ARRAY['dinner']::text[], 'plate', 300, 380, 8.5, 52, 14.5, 3.2, 2.8, 95, 0.15, 680, false),
  (280, 'Puff Puff (Nigerian Doughnuts)', 'West African', 'african', 'vegan', true, 'snack', '4', '15 min', '15 min', 'Airy, yeasted Nigerian doughnuts that puff into rounds as they fry — the original West African street snack, perfectly simple.', 'A full 45-minute rest is important — under-proofed puff puff will not be airy and will absorb more oil during frying.', 'Traditional', NULL, ARRAY['2 cups plain flour','1 tsp instant yeast','3 tbsp sugar','1/2 tsp nutmeg','1/4 tsp salt','1 cup warm water','Oil for deep frying']::text[], ARRAY['Combine flour, yeast, sugar, nutmeg and salt; add warm water; mix to a smooth batter (thicker than pancake batter).','Cover and rest 45 min-1 hour until bubbly and slightly risen.','Heat oil to 175°C; use a wet hand or two spoons to drop balls of batter into the oil.','Fry 3-4 min, turning, until golden on all sides.','Drain on paper; dust with sugar if desired; eat warm.']::text[], ARRAY['snack']::text[], 'piece', 70, 240, 3.2, 28.5, 11.8, 0.9, 1.8, 24, 0, 185, false),
  (281, 'Chin Chin', 'West African', 'african', 'egg', true, 'snack', '6', '20 min', '20 min', 'Deep-fried strips or knots of sweetened dough, crunchy throughout — Nigeria and Ghana''s ubiquitous snack that keeps for weeks in a tin.', 'Frying on lower heat for longer is the secret to chin chin that is crunchy all the way through rather than just on the outside.', 'Traditional', NULL, ARRAY['2 cups plain flour','3 tbsp sugar','1/2 tsp salt','1/2 tsp nutmeg','30g cold butter, cubed','1 egg','3 tbsp milk (approx)','Oil for deep frying']::text[], ARRAY['Rub butter into flour until like breadcrumbs; stir in sugar, salt and nutmeg.','Beat egg with milk; add to flour mixture; mix to a stiff, smooth dough — add more milk if needed.','Roll thin (3-4mm); cut into small strips or knot shapes.','Deep fry at 160°C in batches until golden throughout — 5-6 min on low heat.','Drain fully; cool completely before storing — they crisp up as they cool.']::text[], ARRAY['snack']::text[], 'serving', 45, 190, 3.2, 22.5, 8.8, 0.7, 1.1, 32, 0.08, 145, false),
  (282, 'Plantain Chips', 'West African', 'african', 'vegan', true, 'snack', '2', '5 min', '15 min', 'Thinly sliced unripe plantain fried until wafer-crisp and salted — West Africa''s original crisp, eaten from street stalls across the continent.', 'Paper-thin slices are non-negotiable — thick slices take too long and cook unevenly, becoming oily in the centre before the surface crisps.', 'Traditional', NULL, ARRAY['2 green (unripe) plantains, peeled','Oil for deep frying','1 tsp fine sea salt','Optional: chilli powder or suya spice for dusting']::text[], ARRAY['Slice plantains paper-thin on a mandoline or with a sharp knife; pat completely dry.','Fry in small batches at 175°C until golden and completely crisp — 2-3 min.','They should be rigid, not flexible, when done.','Drain immediately; salt while hot; dust with chilli if using.','Cool completely before packing — they become crispier as they cool.']::text[], ARRAY['snack']::text[], 'serving', 40, 150, 1.2, 17.5, 7.8, 1.4, 0.4, 8, 0, 290, false),
  (283, 'Bofrot (Ghanaian Sweet Doughnuts)', 'West African', 'african', 'egg', true, 'snack', '4', '30 min', '15 min', 'Slightly sweet, coconut-scented Ghanaian doughnuts — denser and smaller than Nigerian puff puff, with a characteristic pale golden colour and smooth skin.', 'Bofrot should be pale golden, not deeply brown — the coconut milk in the dough browns faster than a plain dough and over-browning turns them bitter.', 'Traditional', NULL, ARRAY['2 cups plain flour','2 tbsp sugar','1/2 tsp instant yeast','1/4 cup coconut milk','1 egg','Warm water to mix (approx 1/2 cup)','Oil for deep frying']::text[], ARRAY['Combine flour, sugar and yeast; add egg, coconut milk and enough warm water to form a soft, sticky dough.','Knead briefly; cover and prove 30-45 min until slightly risen.','Wet hands; shape into small balls (walnut-sized).','Fry at 165°C until pale golden — 4-5 min — turning frequently for even colour.','Drain; dust with icing sugar if desired.']::text[], ARRAY['snack']::text[], 'piece', 65, 220, 5.2, 28.5, 8.1, 0.9, 1.8, 42, 0.18, 156, false),
  (284, 'Suya-Spiced Groundnuts', 'West African', 'african', 'vegan', false, 'snack', '4', '5 min', '10 min', 'Peanuts tossed in a suya spice paste and roasted until fragrant and lightly crusted — the bar snack and roadside snack of Nigeria and beyond.', 'Remove the peanuts from the oven when they smell toasted but still look lightly coloured — carryover heat will finish them and they burn quickly past this point.', 'Traditional', NULL, ARRAY['2 cups raw shelled peanuts','2 tbsp groundnut powder (or fine peanut butter powder)','1 tsp paprika','1 tsp ginger','1/2 tsp cayenne pepper','1/2 tsp garlic powder','1/2 tsp onion powder','1 tsp salt','1 tbsp vegetable oil']::text[], ARRAY['Mix all spices with oil and peanut powder to form a coating paste.','Toss raw peanuts in the paste until evenly coated.','Spread on a baking tray; roast at 180°C for 8-10 min, shaking halfway, until fragrant and lightly toasted.','Cool completely — they crisp and the spice sets as they cool.','Store in an airtight jar; they keep for one week.']::text[], ARRAY['snack']::text[], 'serving', 35, 210, 9.2, 7.8, 18.5, 1.8, 1.9, 42, 0, 580, false),
  (285, 'Dhokla', 'North Indian', 'west_indian', 'veg', true, 'snack', '4', '10 min + 1 hr ferment', '20 min', 'Light, spongy steamed cakes made from fermented gram flour — Gujarat''s beloved breakfast bite, tangy and cloud-soft.', 'Add the Eno and pour into the steamer in one swift motion — any delay and the batter loses its rise.', 'Traditional', NULL, ARRAY['1½ cups gram flour (besan)','¾ cup yogurt','½ tsp turmeric','1 tsp ginger-chili paste','1 tsp Eno fruit salt','salt to taste','For tempering: 1 tbsp oil','1 tsp mustard seeds','8–10 curry leaves','2 green chilies slit','1 tbsp sugar','2 tbsp water','fresh coriander and grated coconut to garnish']::text[], ARRAY['Mix gram flour, yogurt, turmeric, ginger-chili paste, and salt into a smooth batter. Rest 30–60 min.','Grease a round tray. Add Eno to batter, stir quickly — batter will foam up.','Pour into tray immediately; steam 12–15 min until a toothpick comes out clean.','Cool 5 min, then cut into squares.','Heat oil, splutter mustard seeds, curry leaves, and chilies. Add sugar and water; pour over dhokla.','Garnish with coriander and coconut. Serve with green chutney.']::text[], ARRAY['breakfast','snack']::text[], 'serving', 120, 180, 6.2, 22.8, 5.1, 1.8, 1.4, 68, 0.15, 380, false),
  (286, 'Vegetable Uttapam', 'South Indian', 'south_indian', 'vegan', false, 'main', '2', '5 min', '15 min', 'Thick, spongy dosa-style pancakes studded with colourful vegetables — a wholesome South Indian breakfast that is as pretty as it is filling.', 'Use well-fermented batter — thin or under-fermented batter gives flat, dense uttapam rather than the characteristic spongy texture.', 'Traditional', NULL, ARRAY['2 cups fermented dosa batter','½ small onion (finely chopped)','1 small tomato (deseeded, chopped)','1 green chili (finely chopped)','small handful fresh coriander','oil for cooking']::text[], ARRAY['Heat a tawa on medium; grease lightly.','Pour a ladleful of batter; spread gently into a thick circle — do not thin like a dosa.','Scatter onion, tomato, chili, and coriander on top; press lightly.','Drizzle oil around edges; cook until base is golden and set.','Flip carefully; cook 2 min on the vegetable side.','Serve hot with coconut chutney and sambar.']::text[], ARRAY['breakfast','dinner','snack']::text[], 'piece', 180, 310, 8.5, 42, 8.2, 2.1, 2.8, 95, 0.15, 380, false),
  (287, 'Paneer Paratha', 'North Indian', 'north_indian', 'veg', true, 'main', '2', '15 min', '15 min', 'Whole-wheat flatbreads stuffed with spiced crumbled paneer — golden, crisp-edged, and utterly satisfying with a dollop of cold butter.', 'Keep the filling dry — wet paneer tears the dough. Squeeze out any liquid from the paneer before mixing with spices.', 'Traditional', NULL, ARRAY['1½ cups whole wheat flour (atta)','water to knead','pinch of salt','200 g paneer (crumbled)','1 green chili (finely chopped)','½ tsp cumin seeds','¼ tsp red chili powder','2 tbsp fresh coriander (chopped)','salt to taste','ghee or butter for cooking']::text[], ARRAY['Knead flour with salt and water into a smooth pliable dough. Rest 15 min.','Mix paneer with chili, cumin, red chili powder, coriander, and salt.','Divide dough into balls; roll each into a disc.','Place filling in centre, gather edges, seal, and roll gently into a flat round.','Cook on a hot tawa with ghee, pressing gently, until golden on both sides.','Serve hot with yogurt, pickle, and butter.']::text[], ARRAY['breakfast']::text[], 'piece', 160, 420, 16.5, 38.2, 18.4, 6.1, 3.8, 185, 0.35, 380, false),
  (288, 'Ragi Dosa', 'South Indian', 'south_indian', 'veg', true, 'main', '2', '5 min', '15 min', 'Crispy, lacy dosas made from finger millet (ragi) and rice flour — a nutritious South Indian breakfast packed with calcium and fibre.', 'Ragi batter does not spread as easily as plain dosa — pour from the centre and ease outward quickly before it sets.', 'Traditional', NULL, ARRAY['½ cup ragi flour (finger millet)','¼ cup rice flour','2 tbsp urad dal flour','¼ cup yogurt','½ tsp cumin seeds','1 green chili (finely chopped)','small piece ginger (grated)','salt to taste','water to make batter','oil for cooking']::text[], ARRAY['Mix all flours with yogurt, cumin, chili, ginger, and salt.','Add water gradually to reach a thin pourable batter. Rest 10 min.','Heat a tawa on high; reduce to medium-high; grease lightly.','Pour a ladleful of batter from the edges inward, spreading as thin as possible.','Drizzle oil around edges; cook until crisp and lightly brown.','Fold and serve with coconut chutney.']::text[], ARRAY['breakfast','dinner']::text[], 'serving', 180, 270, 8.5, 38.2, 6.8, 3.2, 2.1, 95, 0.15, 185, false),
  (289, 'Rava Idli', 'South Indian', 'south_indian', 'veg', true, 'main', '2', '10 min', '15 min', 'Soft, instant idlis made from tempered semolina — no overnight fermentation needed, making this the busy-morning hero of South Indian kitchens.', 'The batter thickens as it rests — add a splash of water if needed before adding Eno, so idlis come out soft, not dense.', 'Traditional', NULL, ARRAY['1 cup fine semolina (rava)','½ cup yogurt','½ tsp mustard seeds','8–10 cashew halves','8–10 curry leaves','2 tbsp oil','1 tsp Eno fruit salt','salt to taste','water as needed','fresh coriander (chopped)']::text[], ARRAY['Heat oil; splutter mustard seeds, cashews, and curry leaves until cashews are golden.','Add semolina; roast on low 3–4 min until fragrant. Cool slightly.','Mix in yogurt, coriander, and salt; add water to get a thick batter.','Rest 10 min — rava absorbs liquid and thickens.','Add Eno; stir gently and spoon into greased idli moulds immediately.','Steam 10–12 min until set. Serve with sambar and coconut chutney.']::text[], ARRAY['breakfast','dinner','snack']::text[], 'serving', 150, 220, 6.5, 28, 8.5, 1.2, 1.8, 95, 0.15, 320, false),
  (290, 'Curd Rice', 'South Indian', 'south_indian', 'veg', true, 'main', '2', '5 min', '20 min', 'Creamy, cooling rice blended with yogurt and finished with a mustard-curry leaf temper — South India''s beloved comfort dish and the traditional finale of a full meal.', 'Use slightly warm rice — mixing yogurt into hot rice curdles it. If rice has cooled completely, a splash of milk brings the creaminess back.', 'Traditional', NULL, ARRAY['1 cup short-grain rice','1½ cups thick yogurt','½ cup milk','salt to taste','1 tsp oil','½ tsp mustard seeds','½ tsp urad dal','1 green chili (finely chopped)','8–10 curry leaves','small piece ginger (grated)','1 dry red chili','pomegranate seeds and fresh coriander to garnish']::text[], ARRAY['Cook rice until soft and slightly overcooked; mash lightly with a spoon while warm.','Cool to room temperature; mix in yogurt and milk until creamy. Season with salt.','Heat oil; splutter mustard seeds and urad dal until dal turns golden.','Add green chili, ginger, curry leaves, and red chili; fry 30 sec.','Pour tempering over rice and mix gently.','Garnish with pomegranate seeds and coriander; serve at room temperature or lightly chilled.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 250, 320, 12.5, 38.2, 8.1, 0.8, 1.2, 185, 0.6, 285, false),
  (291, 'Paneer Butter Masala', 'North Indian', 'north_indian', 'veg', false, 'curry', '3', '10 min', '25 min', 'Velvety, mildly spiced tomato-cream gravy cradling golden paneer cubes — the restaurant classic that has won hearts far beyond India.', 'Blanching and pureeing the tomatoes gives a smoother, sweeter gravy — the skin and seeds are the source of any bitterness.', 'Traditional', NULL, ARRAY['250 g paneer (cubed)','3 large tomatoes (blanched and pureed)','1 large onion (pureed)','2 tbsp butter','1 tbsp oil','1 tbsp ginger-garlic paste','1 tsp red chili powder','1 tsp coriander powder','½ tsp garam masala','½ tsp kasuri methi','3 tbsp fresh cream','salt to taste','fresh coriander to garnish']::text[], ARRAY['Heat oil; sauté onion puree until it leaves oil, about 10 min on medium.','Add ginger-garlic paste; cook 2 min. Add spices and cook 1 min.','Pour in tomato puree; simmer until thick and oil separates, 8–10 min.','Stir in butter and cream; simmer 2 min.','Add paneer cubes; fold gently and simmer 3 min.','Crush kasuri methi between palms; stir in. Garnish with coriander and a swirl of cream.']::text[], ARRAY['lunch']::text[], 'bowl', 200, 490, 18.5, 12.8, 32.4, 1.2, 1.8, 285, 0.68, 520, false),
  (292, 'Jeera Rice', 'North Indian', 'north_indian', 'veg', true, 'staple', '2', '5 min', '20 min', 'Fragrant basmati rice tempered with cumin in ghee — the simplest, most aromatic side that elevates any dal or curry.', 'Soaking the rice shortens cooking time and keeps grains from sticking — each grain should be separate and elongated.', 'Traditional', NULL, ARRAY['1 cup basmati rice (soaked 15 min, drained)','1¾ cups water','1½ tbsp ghee','1 tsp cumin seeds','½ tsp salt','fresh coriander to garnish']::text[], ARRAY['Heat ghee in a heavy-bottomed pot; add cumin seeds and let sizzle until fragrant, about 30 sec.','Add rice; stir and coat with ghee for 1 min.','Pour in water and salt; bring to a boil.','Reduce heat to very low, cover tightly, and cook 12–15 min until water is absorbed.','Rest covered 5 min; fluff with a fork. Garnish with coriander.']::text[], ARRAY['lunch','dinner']::text[], 'bowl', 200, 320, 6.5, 52, 11.5, 0.8, 0.6, 18, 0.08, 290, false),
  (293, 'Aloo Gobi', 'North Indian', 'north_indian', 'vegan', false, 'side', '3', '10 min', '25 min', 'Potatoes and cauliflower tumbled in a dry masala of warming spices — a no-gravy North Indian staple that pairs perfectly with roti.', 'Keep the lid on and resist adding water — the cauliflower releases enough moisture to cook everything through without making it watery.', 'Traditional', NULL, ARRAY['2 medium potatoes (peeled, cubed)','1 small cauliflower (cut into florets)','1 medium onion (sliced)','2 tomatoes (chopped)','2 tbsp oil','1 tsp cumin seeds','1 tsp ginger (grated)','1 green chili (chopped)','½ tsp turmeric','1 tsp coriander powder','½ tsp red chili powder','½ tsp garam masala','salt to taste','fresh coriander to garnish']::text[], ARRAY['Parboil potato cubes 5 min; drain.','Heat oil; splutter cumin. Add onion; cook until golden.','Add ginger, chili, and tomato; cook until soft and oil separates.','Stir in turmeric, coriander powder, and red chili; fry 1 min.','Add potatoes and cauliflower; stir to coat. Season with salt.','Cover and cook on low-medium 15 min, stirring occasionally, until vegetables are tender.','Sprinkle garam masala and coriander; toss and serve.']::text[], ARRAY['lunch','dinner','breakfast']::text[], 'katori', 150, 230, 4.2, 28.5, 8.1, 3.8, 1.2, 35, 0, 285, false),
  (294, 'Bhindi Masala', 'North Indian', 'north_indian', 'vegan', false, 'side', '2', '10 min', '20 min', 'Okra tossed with spiced onion-tomato masala until perfectly non-slimy and moreish — a North Indian favourite that converts even okra sceptics.', 'High heat and a dry pan are the secret to slime-free bhindi — wash okra the night before and air-dry uncovered overnight.', 'Traditional', NULL, ARRAY['300 g okra (bhindi, washed, dried completely, sliced)','1 large onion (sliced)','2 tomatoes (chopped)','2 tbsp oil','½ tsp cumin seeds','1 tsp coriander powder','½ tsp turmeric','½ tsp red chili powder','¼ tsp amchur (dry mango powder)','salt to taste','fresh coriander to garnish']::text[], ARRAY['Ensure okra is completely dry before cutting — moisture causes sliminess.','Heat oil on high; fry okra in a single layer until exterior is dry and lightly browned, 8–10 min. Remove.','In the same pan, fry cumin then onion until golden.','Add tomato and spices; cook until oil separates.','Return okra; toss gently to coat. Cook 3–4 min.','Finish with amchur and coriander; serve dry.']::text[], ARRAY['lunch','dinner','breakfast']::text[], 'katori', 150, 190, 3.2, 12.8, 14.5, 2.4, 0.9, 68, 0, 285, false),
  (295, 'Paneer Bhurji', 'North Indian', 'north_indian', 'veg', false, 'side', '2', '5 min', '15 min', 'Scrambled spiced paneer with onion and tomato — the North Indian answer to scrambled eggs, ready in minutes and endlessly versatile.', 'Do not overcook once the paneer is added — bhurji should be moist and crumbly, not dry or rubbery.', 'Traditional', NULL, ARRAY['200 g paneer (crumbled)','1 medium onion (finely chopped)','2 tomatoes (finely chopped)','2 green chilies (finely chopped)','2 tbsp oil','½ tsp cumin seeds','1 tsp ginger-garlic paste','½ tsp turmeric','½ tsp red chili powder','½ tsp garam masala','salt to taste','fresh coriander (chopped)','squeeze of lemon']::text[], ARRAY['Heat oil; splutter cumin. Add onion; sauté until golden.','Add ginger-garlic paste and chili; fry 1 min.','Add tomato and spices; cook until masala thickens and oil separates.','Add crumbled paneer; stir and toss to coat. Cook 2–3 min.','Squeeze lemon; garnish with coriander. Serve with roti or pav.']::text[], ARRAY['lunch']::text[], 'katori', 150, 340, 18.5, 8.2, 26.1, 1.8, 2.1, 285, 0.45, 520, false),
  (296, 'Vegetable Pulao', 'North Indian', 'north_indian', 'veg', false, 'main', '3', '10 min', '25 min', 'Basmati rice cooked with whole spices and seasonal vegetables — lighter than biryani, quicker to make, and fragrant enough to stand alone.', 'Do not stir after adding water — hands-off cooking preserves grain integrity and keeps each rice grain separate.', 'Traditional', NULL, ARRAY['1 cup basmati rice (soaked 15 min)','1 cup mixed vegetables (peas, carrot, beans)','1 medium onion (sliced)','2 tbsp ghee','1 bay leaf','1 cinnamon stick','4 green cardamoms','4 cloves','1 tsp cumin seeds','1 tsp ginger-garlic paste','½ tsp turmeric','1¾ cups water or light stock','salt to taste','fried onions and fresh mint to garnish']::text[], ARRAY['Heat ghee; add whole spices and let sizzle 30 sec.','Add onion; sauté until light golden.','Add ginger-garlic paste; cook 1 min.','Add vegetables and turmeric; stir 2 min.','Add drained rice; stir gently to coat with ghee.','Pour in water and salt; bring to a boil.','Reduce to very low heat, cover tightly, and cook 15 min. Rest 5 min before opening.','Fluff gently; garnish with fried onion and fresh mint.']::text[], ARRAY['lunch']::text[], 'plate', 250, 380, 8.2, 52.1, 11.8, 2.4, 1.6, 48, 0.08, 285, false),
  (297, 'Paneer Tikka Masala', 'North Indian', 'north_indian', 'veg', false, 'curry', '3', '20 min', '30 min', 'Smoky grilled paneer cubes returned to a rich spiced tomato-cashew gravy — the tandoor flavour you do not need a clay oven to recreate.', 'The char on the paneer is non-negotiable — it is what separates tikka masala from a plain paneer curry. Use a very hot pan and let the paneer sit undisturbed.', 'Traditional', NULL, ARRAY['250 g paneer (cubed)','½ cup thick yogurt','1 tsp red chili powder','1 tsp garam masala','1 tsp coriander powder','1 tbsp ginger-garlic paste','1 tbsp oil for marinade','salt to taste','3 tomatoes (pureed)','1 onion (pureed)','2 tbsp cashews (soaked, ground to paste)','2 tbsp oil for gravy','1 tsp cumin powder','½ tsp garam masala','2 tbsp cream','kasuri methi to finish']::text[], ARRAY['Mix yogurt, spices, ginger-garlic paste, and oil; marinate paneer at least 30 min.','Grill or pan-fry marinated paneer on high heat until charred on edges. Set aside.','Sauté onion puree until golden; add ginger-garlic paste.','Add tomato puree and spices; simmer until oil separates, about 10 min.','Stir in cashew paste and cream; simmer 3 min until thick.','Add grilled paneer; simmer 2 min. Crush and stir in kasuri methi. Serve with naan or rice.']::text[], ARRAY['dinner']::text[], 'bowl', 200, 460, 18.5, 12.8, 28.2, 1.2, 1.8, 185, 0.35, 420, false),
  (298, 'Khichdi', 'North Indian', 'pan_indian', 'veg', true, 'main', '3', '5 min', '25 min', 'Rice and moong dal simmered to a gentle porridge-like softness with ghee and cumin — India''s ultimate comfort food, and the dish every grandmother swears by.', 'The consistency is a personal choice — add another half-cup of water for a thinner flowing khichdi, or less for a stiffer version. Both are correct.', 'Traditional', NULL, ARRAY['½ cup basmati rice','¼ cup yellow moong dal (split, skinless)','1 tbsp ghee','1 tsp cumin seeds','¼ tsp turmeric','1 green chili (slit)','salt to taste','2½ cups water']::text[], ARRAY['Wash rice and dal together; soak 10 min.','Heat ghee; add cumin and let splutter.','Add green chili and turmeric; fry 15 sec.','Add rice, dal, salt, and water; stir once.','Pressure cook 2–3 whistles, or simmer covered 20–25 min, until soft and porridge-like.','Add more ghee if desired; serve with papad and pickle.']::text[], ARRAY['lunch']::text[], 'bowl', 250, 340, 8.5, 42.3, 5.8, 1.2, 1.8, 28, 0.08, 320, false),
  (299, 'Chapati (Roti)', 'Pan-Indian', 'pan_indian', 'veg', true, 'staple', '2', '10 min (+ 20 min rest)', '15 min', 'Soft whole-wheat flatbread — the daily bread of India. Made fresh at every meal across the country, from Kashmir to Kanyakumari.', 'A well-rested dough (20 min) and a hot tawa are the two things that make chapati soft. Press gently with a folded cloth as it puffs.', 'Staple', NULL, ARRAY['1 cup whole wheat flour (atta)','½ tsp salt','water to knead (about ½ cup)','ghee to finish']::text[], ARRAY['Mix flour and salt; add water gradually, kneading 5–8 min until smooth and elastic. Rest 15 min.','Divide into balls; roll each into a thin 6–7 inch circle, dusting with flour.','Cook on a hot tawa 30–40 sec until small bubbles appear; flip.','Cook 30 sec more; then hold directly over an open flame 10–15 sec until it puffs.','Brush with ghee; serve immediately.']::text[], ARRAY['breakfast','lunch','dinner']::text[], 'piece', 45, 120, 4.2, 20.1, 3.5, 3.2, 1.8, 18, 0.05, 290, false),
  (300, 'Onion Pakora', 'North Indian', 'north_indian', 'vegan', false, 'snack', '3', '10 min', '15 min', 'Crispy, lacy fritters of thinly sliced onion bound in spiced gram flour batter — the ultimate Indian monsoon snack with a cup of chai.', '170 °C — not screaming hot — ensures the inside cooks through before the outside burns.', 'Traditional', NULL, ARRAY['2 large onions (thinly sliced)','1 cup gram flour (besan)','1 green chili (finely chopped)','1 tsp cumin seeds','½ tsp red chili powder','¼ tsp turmeric','small bunch coriander (chopped)','salt to taste','oil for deep frying','chaat masala to sprinkle']::text[], ARRAY['Mix gram flour with chili, cumin, red chili powder, turmeric, coriander, and salt.','Add onion slices and toss; the onion releases moisture — add only 1–2 tbsp water if needed.','Heat oil to 170 °C; drop small clusters into oil.','Fry on medium-high 4–5 min, turning once, until golden and crisp.','Drain; sprinkle chaat masala. Serve immediately with mint chutney.']::text[], ARRAY['snack']::text[], 'serving', 100, 390, 8.5, 32, 18.5, 4.2, 2.8, 45, 0, 520, false),
  (301, 'Pav Bhaji', 'North Indian', 'west_indian', 'veg', false, 'main', '3', '15 min', '30 min', 'A vibrant, well-seasoned mash of mixed vegetables cooked with butter and pav bhaji masala, served with toasted buttered buns — Mumbai street food at its best.', 'Mash the bhaji directly in the pan while it cooks — the repetitive mashing creates the characteristic almost creamy texture.', 'Traditional', NULL, ARRAY['3 medium potatoes (boiled and mashed)','1 cup cauliflower (boiled and mashed)','½ cup peas (boiled)','1 large onion (finely chopped)','3 tomatoes (finely chopped)','1 capsicum (finely chopped)','3 tbsp butter','1½ tbsp pav bhaji masala','1 tsp red chili powder','½ tsp turmeric','salt to taste','6 pav buns (dinner rolls)','lemon wedges, raw onion and coriander to serve']::text[], ARRAY['Heat 2 tbsp butter; sauté onion until golden. Add capsicum; cook 2 min.','Add tomato and all spices; cook until oil separates, about 8 min.','Add mashed potato, cauliflower, and peas; mash everything together in the pan.','Add water to desired consistency; simmer 10 min, stirring often.','Adjust seasoning; top with remaining butter.','Slit pav buns; toast on a buttered tawa until golden. Serve with bhaji, lemon, onion, and coriander.']::text[], ARRAY['snack']::text[], 'plate', 350, 420, 12.5, 52, 14.2, 5.8, 2.1, 95, 0.35, 480, false),
  (302, 'Kachori', 'North Indian', 'north_indian', 'vegan', true, 'snack', '4', '20 min', '20 min', 'Flaky, deep-fried pastry shells filled with spiced moong dal — a North Indian snack beloved from Rajasthan to Bengal.', 'Fry kachoris low and slow — high heat browns the outside before the inside is cooked, leaving raw-tasting dough at the centre.', 'Traditional', NULL, ARRAY['1 cup all-purpose flour (maida)','2 tbsp oil','pinch of salt','water to knead','½ cup yellow moong dal (soaked, drained)','1 tsp fennel seeds','½ tsp cumin','½ tsp red chili powder','¼ tsp garam masala','¼ tsp turmeric','2 tsp oil for filling','salt to taste','oil for deep frying']::text[], ARRAY['Mix flour, oil, and salt; add water gradually to make a firm dough. Rest 20 min.','Blend soaked dal coarsely. Fry with oil and all spices until dry and aromatic. Cool.','Divide dough; roll each into a small disc. Place filling, gather edges, and seal.','Flatten gently into a puri shape without tearing.','Deep fry on low-medium heat 8–10 min, turning frequently, until golden and crisp all through.','Serve hot with tamarind chutney and mint chutney.']::text[], ARRAY['snack','breakfast']::text[], 'piece', 70, 310, 8.2, 32.5, 16.8, 2.1, 2.4, 45, 0, 285, false),
  (303, 'Murukku', 'South Indian', 'south_indian', 'veg', true, 'snack', '6', '20 min', '20 min', 'Crunchy, spiral-shaped rice flour snacks seasoned with cumin and sesame — a South Indian festival staple that disappears from the tin before you can blink.', 'The dough must be firm enough to hold shape through the press — too soft and spirals collapse; too stiff and the dough cracks.', 'Traditional', NULL, ARRAY['1 cup rice flour','¼ cup urad dal flour (roasted)','½ tsp cumin seeds','½ tsp sesame seeds','¼ tsp red chili powder','1 tbsp butter','salt to taste','hot water to knead','oil for deep frying']::text[], ARRAY['Mix both flours, spices, and butter; add hot water gradually to make a stiff but pliable dough.','Rest 5 min. Fill a murukku press or piping bag with a star nozzle.','Pipe spirals onto a greased surface or directly into oil.','Deep fry in batches at 160–170 °C, turning gently, until the sizzling subsides and murukku is crisp.','Drain; cool completely — they crisp up further as they cool.','Store airtight for up to 2 weeks.']::text[], ARRAY['snack']::text[], 'serving', 50, 380, 6.2, 42.8, 16.5, 1.8, 2.1, 68, 0.08, 185, false),
  (304, 'Kheer (Rice Pudding)', 'North Indian', 'north_indian', 'veg', true, 'dessert', '4', '5 min', '40 min', 'Slow-cooked rice melted into creamy cardamom-scented full-fat milk, crowned with pistachios and rose petals — the quintessential Indian celebration dessert.', 'Stir frequently and use a heavy pot — milk scorches easily on the base and leaves a burnt flavour throughout.', 'Traditional', NULL, ARRAY['3 tbsp short-grain rice (washed)','1 litre full-fat milk','4 tbsp sugar','4 green cardamoms (pods crushed)','1 tbsp pistachios (slivered)','1 tbsp almonds (slivered)','1 tsp rose water','pinch of saffron dissolved in 1 tbsp warm milk']::text[], ARRAY['Bring milk to a boil in a heavy-bottomed pot; add rice.','Simmer on low, stirring every 5 min, for 30–35 min until rice is very soft and milk reduced by one-third.','Add sugar and cardamom; stir until dissolved. Simmer 5 min more.','Stir in saffron milk and rose water; remove from heat.','Serve warm, or chill 2–3 hours. Garnish with nuts and rose petals before serving.']::text[], ARRAY['snack']::text[], 'bowl', 200, 450, 8.2, 52.5, 16.8, 1.2, 0.8, 285, 0.55, 95, false),
  (306, 'Gulab Jamun', 'North Indian', 'north_indian', 'veg', true, 'dessert', '4', '20 min', '20 min', 'Soft, doughnut-like milk solid balls soaked in saffron and cardamom-scented sugar syrup — served warm, they dissolve with almost startling ease.', 'Fry on the lowest possible heat — gulab jamun must cook from inside out; high heat gives a dark shell with a raw doughy centre.', 'Traditional', NULL, ARRAY['1 cup khoya (mawa, or use full-fat milk powder)','2 tbsp all-purpose flour','pinch of baking soda','ghee to knead','milk to bind','oil or ghee for deep frying','1 cup sugar','1 cup water','4 green cardamoms','pinch of saffron','1 tsp rose water']::text[], ARRAY['Boil sugar and water to a sticky syrup; add cardamom, saffron, and rose water. Keep warm.','Mix khoya, flour, and baking soda; add just enough milk and ghee to make a soft non-sticky dough.','Shape into smooth oval balls with no cracks.','Deep fry on very low heat, turning continuously, until dark golden brown, 8–10 min.','Drain briefly; soak immediately in warm syrup at least 30 min before serving.','Serve warm, 2–3 per portion.']::text[], ARRAY['snack','lunch','dinner','breakfast']::text[], 'piece', 45, 160, 3.5, 28, 8.5, 0.2, 0.4, 85, 0.15, 32, false),
  (307, 'Jalebi', 'North Indian', 'north_indian', 'veg', true, 'dessert', '4', '10 min + overnight ferment', '15 min', 'Pretzel-shaped deep-fried batter spirals, crackling crisp and soaked to the core in warm saffron syrup — the joyous orange swirls of every Indian celebration.', 'Syrup must be warm, not cold or boiling — cold syrup makes jalebi soggy, boiling syrup causes crystallisation on the surface.', 'Traditional', NULL, ARRAY['1 cup all-purpose flour (maida)','1 tbsp yogurt','pinch of turmeric for colour','water to make thin batter','oil for deep frying','1 cup sugar','½ cup water','pinch of saffron','few drops rose water','¼ tsp cardamom powder']::text[], ARRAY['Mix flour, yogurt, turmeric, and water into a smooth lump-free batter slightly thinner than dosa batter. Cover and ferment overnight.','Boil sugar and water to one-string consistency; add saffron, rose water, and cardamom. Keep warm.','Heat oil in a flat shallow pan to 170 °C. Fill a squeeze bottle with batter.','Pipe concentric circles into the oil; fry 2–3 min per side until crisp.','Drain briefly; soak in warm syrup 1–2 min. Serve immediately — jalebi are best eaten hot.']::text[], ARRAY['snack','breakfast','lunch','dinner']::text[], 'piece', 60, 300, 3.2, 48.5, 11.8, 0.4, 1.2, 28, 0.08, 52, false),
  (308, 'Besan Ladoo', 'North Indian', 'north_indian', 'veg', true, 'dessert', '6', '5 min', '20 min', 'Golden roasted gram flour balls bound with ghee and scented with cardamom — the celebratory sweet that every Indian household makes for festivals and happy occasions.', 'Roast gram flour all the way to a deep golden colour — under-roasted besan leaves an unpleasant raw aftertaste in the finished ladoo.', 'Traditional', NULL, ARRAY['1 cup gram flour (besan)','¼ cup ghee','½ cup icing sugar (powdered)','½ tsp cardamom powder','1 tbsp cashews (chopped)','1 tbsp raisins']::text[], ARRAY['Heat ghee in a heavy pan; add gram flour.','Roast on low heat, stirring continuously, 12–15 min until flour turns golden and smells nutty.','Remove from heat; cool until just warm.','Add icing sugar, cardamom, cashews, and raisins; mix well.','Shape into round balls while still warm — the mixture firms as it cools.','Cool completely; store airtight up to 2 weeks.']::text[], ARRAY['snack']::text[], 'piece', 40, 260, 7.2, 28.5, 11.8, 1.4, 1.8, 42, 0.1, 18, false),
  (309, 'Masala Chai', 'North Indian', 'north_indian', 'veg', true, 'drink', '2', '2 min', '8 min', 'Strong black tea simmered with ginger, cardamom, and spices in equal parts milk and water — India''s unofficial national drink, comforting at any hour.', 'Add the tea after the spices have had 2 minutes in the water — the spices open up first and infuse more deeply into the chai.', 'Traditional', NULL, ARRAY['1 cup water','1 cup full-fat milk','2 tsp loose Assam black tea','2 green cardamom pods (lightly crushed)','1 small piece ginger (bruised)','1 small piece cinnamon stick','2 cloves','2 tsp sugar']::text[], ARRAY['Bring water to a boil; add ginger, cardamom, cinnamon, and cloves.','Simmer 2 min to release the spices.','Add tea leaves; simmer 1 min.','Pour in milk; bring back to a gentle boil, then simmer 3–4 min until colour deepens.','Add sugar; stir to dissolve.','Strain into cups; serve hot.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'cup', 150, 90, 3.2, 10.8, 3.1, 0.1, 0.3, 118, 0.38, 42, false),
  (310, 'Rava Kesari', 'South Indian', 'south_indian', 'veg', true, 'dessert', '4', '5 min', '20 min', 'Saffron-gold semolina halwa shimmering with ghee and studded with cashews — South India''s festival sweet that doubles as a celebratory breakfast offering.', 'Pour the boiling water all at once and stir fast — lumps form when water is added gradually. A smooth kesari has a silky, jewel-like finish.', 'Traditional', NULL, ARRAY['1 cup fine semolina (rava)','1¼ cups sugar','3 cups water','¼ cup ghee','pinch of saffron','¼ tsp cardamom powder','2 tbsp cashews','1 tbsp raisins']::text[], ARRAY['Heat 1 tbsp ghee; fry cashews until golden; remove. Fry raisins until plump; remove.','Roast semolina in the same pan on medium, stirring, 4–5 min until fragrant.','Dissolve saffron in 2 tbsp warm water; add to the measured water.','Bring saffron water to a boil; pour carefully over roasted semolina.','Stir continuously on medium until water is absorbed and rava thickens.','Add sugar; stir vigorously — it loosens first, then thickens again.','Add remaining ghee in 2 additions, stirring between each, until glossy.','Fold in cashews, raisins, and cardamom. Serve warm.']::text[], ARRAY['snack']::text[], 'bowl', 120, 360, 6.2, 52.8, 15.4, 1.1, 1.8, 45, 0.1, 28, false),
  (311, 'Filter Coffee', 'South Indian', 'south_indian', 'veg', true, 'drink', '1', '5 min', '10 min', 'Strong decoction drip-brewed through a brass filter, then mixed with hot frothy milk — the ritual morning cup of Tamil Nadu and Karnataka.', NULL, 'Traditional', NULL, ARRAY['Coffee powder — 2 tbsp','Hot water — 125 ml','Full-fat milk — 1 cup','Sugar — 1 tsp']::text[], ARRAY['Add coffee powder to the upper compartment of a metal filter. Pour hot (not boiling) water over it and let the decoction drip through — takes 5–10 min.','Pour decoction and sugar into a tumbler.','Heat milk until steaming. Pour over the decoction.','Pour the mixture back and forth between the tumbler and davara several times to froth and aerate. Serve immediately.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'cup', 150, 80, 8.2, 11.8, 5.1, 0, 0.4, 296, 0.42, 106, false),
  (312, 'Haldi Doodh (Golden Milk)', 'North Indian', 'north_indian', 'veg', true, 'drink', '1', '2 min', '8 min', 'Warm milk simmered with turmeric, black pepper, and honey — an ancient Indian remedy that has become a global wellness staple.', NULL, 'Traditional', NULL, ARRAY['Full-fat milk — 1 cup','Turmeric powder — 1/2 tsp','Black pepper — a pinch','Honey — 1 tsp','Cardamom powder — a pinch','Fresh ginger (grated) — 1/4 tsp']::text[], ARRAY['Heat milk in a saucepan over medium heat.','Add turmeric, black pepper, cardamom and ginger. Stir well.','Simmer 5 minutes without boiling.','Remove from heat. Stir in honey.','Strain into a mug and serve hot.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 200, 130, 8.2, 12.1, 7.3, 0.2, 0.3, 285, 0.5, 105, false),
  (313, 'Badam Milk (Almond Milk)', 'North Indian', 'north_indian', 'veg', true, 'drink', '1', '10 min', '10 min', 'Saffron-tinted warm milk enriched with ground soaked almonds and cardamom — festive, nourishing, and loved from Kashmir to Kerala.', NULL, 'Traditional', NULL, ARRAY['Full-fat milk — 2 cups','Almonds — 15 (soaked overnight and peeled)','Saffron — a generous pinch','Sugar — 2 tsp','Cardamom powder — 1/4 tsp','Pistachios — 5 (sliced, for garnish)']::text[], ARRAY['Dissolve saffron in 1 tbsp warm milk and set aside.','Blend soaked almonds with 1/4 cup milk to a very smooth paste.','Heat remaining milk. Add sugar, cardamom and saffron milk. Stir to combine.','Stir in almond paste. Simmer on low 5–7 minutes, stirring continuously.','Pour into a glass and garnish with sliced pistachios. Serve hot or chilled.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 250, 190, 8.2, 14.5, 8.1, 1.2, 0.8, 298, 0.42, 98, false),
  (314, 'Ginger Lemon Tea', 'North Indian', 'north_indian', 'veg', true, 'drink', '1', '2 min', '8 min', 'A sharp, cleansing brew of fresh ginger and black tea brightened with lemon and honey — a brisk, energising start to the morning.', NULL, 'Traditional', NULL, ARRAY['Water — 1.5 cups','Fresh ginger — 1/2 inch (sliced thin)','Black tea leaves — 1 tsp','Fresh lemon juice — 1 tbsp','Honey — 1 tsp']::text[], ARRAY['Bring water to a boil with ginger slices. Reduce heat, simmer 3 minutes.','Add tea leaves and steep 2 minutes.','Strain into a cup.','Stir in lemon juice and honey. Serve hot.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'cup', 200, 25, 0.2, 6.5, 0.1, 0.2, 0.3, 8, 0, 2, false),
  (315, 'Nimbu Pani (Indian Lemonade)', 'North Indian', 'north_indian', 'vegan', true, 'drink', '1', '5 min', '0 min', 'Fresh lime juice in chilled water with a pinch of black salt and roasted cumin — India''s ubiquitous street cooler, endlessly refreshing in any season.', NULL, 'Traditional', NULL, ARRAY['Fresh lime juice — 2 tbsp','Cold water — 1 cup','Sugar — 1 tsp','Black salt (kala namak) — a pinch','Roasted cumin powder — 1/4 tsp','Fresh mint — 2 sprigs','Ice cubes — as needed']::text[], ARRAY['Combine lime juice, sugar, black salt and cumin powder in a tall glass.','Add chilled water and stir until sugar dissolves.','Add ice cubes and fresh mint sprigs.','Taste and adjust salt or sugar. Serve immediately.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 250, 40, 0.1, 10.2, 0, 0.3, 0.2, 8.5, 0, 120, false),
  (316, 'Chaas / Mor (Spiced Buttermilk)', 'South Indian', 'south_indian', 'veg', true, 'drink', '1', '5 min', '0 min', 'Thin, savory yogurt whisked with water, curry leaves and ginger — a cooling digestive served at the end of a South Indian or Gujarati meal.', NULL, 'Traditional', NULL, ARRAY['Fresh curd (yogurt) — 1/2 cup','Cold water — 1 cup','Green chilli — 1/2 (finely chopped)','Fresh ginger — 1/4 inch (grated)','Curry leaves — 6','Fresh coriander — 1 tbsp (chopped)','Roasted cumin powder — 1/4 tsp','Salt — to taste']::text[], ARRAY['Whisk yogurt until completely smooth with no lumps.','Add cold water gradually, whisking to a thin, even consistency.','Stir in green chilli, ginger, cumin powder and salt.','Pour into glasses, garnish with curry leaves and coriander. Serve chilled.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 250, 60, 3.2, 4.1, 1.2, 0.3, 0.4, 142, 0.24, 285, false),
  (317, 'Aam Panna (Raw Mango Cooler)', 'North Indian', 'north_indian', 'vegan', true, 'drink', '4', '5 min', '15 min', 'A tangy-sweet raw mango concentrate with roasted cumin and black salt — the definitive Indian summer cooler, great for heat and digestion.', NULL, 'Traditional', NULL, ARRAY['Raw green mango — 1 medium','Sugar — 3 tbsp','Roasted cumin powder — 1/2 tsp','Black salt (kala namak) — 1/4 tsp','Salt — a pinch','Fresh mint leaves — 8','Cold water — 2 cups']::text[], ARRAY['Boil or pressure-cook the whole mango until completely soft, about 10–15 min.','Cool, peel and squeeze out all the pulp. Discard skin and seed.','Blend pulp with sugar, cumin, black salt, a pinch of salt and mint until smooth.','Refrigerate the concentrate. To serve: stir 3 tbsp concentrate into a glass of cold water. Add ice and mint.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 200, 70, 0.3, 17.5, 0.1, 0.4, 0.1, 8, 0, 85, false),
  (318, 'Jal Jeera', 'North Indian', 'north_indian', 'vegan', true, 'drink', '2', '5 min', '0 min', 'A zesty spiced water drink made with cumin, fresh mint, tamarind and black salt — a traditional digestive served before meals at Indian street stalls.', NULL, 'Traditional', NULL, ARRAY['Roasted cumin powder — 1 tsp','Fresh mint leaves — 15','Tamarind — a small ball (soaked in 1/4 cup water)','Black salt (kala namak) — 1/4 tsp','Fresh ginger — 1/2 inch','Green chilli — 1/2','Fresh lemon juice — 1 tbsp','Sugar — 1/2 tsp','Cold water — 1.5 cups']::text[], ARRAY['Blend mint, ginger and green chilli with 2 tbsp water to a smooth paste.','Squeeze soaked tamarind through the water to extract pulp; discard fibre.','Combine mint paste, tamarind water, cumin, black salt, lemon juice and sugar in a pitcher.','Add cold water, stir and strain into glasses over ice. Garnish with a mint sprig.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 200, 30, 0.3, 6.8, 0.1, 0.4, 0.6, 12, 0, 85, false),
  (319, 'Kokum Sharbat', 'Konkani', 'west_indian', 'vegan', true, 'drink', '4', '5 min', '10 min', 'A deep-purple cooler from the Konkan coast — sun-dried kokum steeped into a tart, sweet syrup then diluted with chilled water.', NULL, 'Traditional', NULL, ARRAY['Dried kokum — 10 pieces','Sugar — 3 tbsp','Rock salt — a pinch','Roasted cumin powder — 1/4 tsp','Cold water — 2 cups']::text[], ARRAY['Soak kokum in 1/2 cup warm water for 15–20 minutes until softened.','Squeeze and press to extract juice. Discard solids.','Add sugar and heat briefly to dissolve. Cool completely.','To serve: add 2–3 tbsp concentrate to a glass of cold water. Stir in cumin and rock salt. Add ice.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 200, 50, 0.1, 12.5, 0.1, 0.3, 0.4, 8, 0, 65, false),
  (320, 'Rose Milk', 'South Indian', 'south_indian', 'veg', true, 'drink', '1', '2 min', '0 min', 'Cold milk sweetened with fragrant rose syrup — a street-stall classic from Tamil Nadu, simple, pink, and deeply nostalgic.', NULL, 'Traditional', NULL, ARRAY['Cold full-fat milk — 1 cup','Rose syrup — 2 tbsp','Ice cubes — as needed','Basil seeds (sabja) — 1/2 tsp (optional, soaked 10 min)']::text[], ARRAY['If using basil seeds, soak in 2 tbsp water for 10 minutes until they bloom translucent.','Pour cold milk into a tall glass.','Add rose syrup and stir until milk turns evenly pink.','Add ice cubes and soaked basil seeds if using. Serve immediately.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 250, 150, 8, 18.5, 4.8, 0.8, 0.2, 290, 0.42, 125, false),
  (321, 'Warm Ginger Honey Tea', 'North Indian', 'north_indian', 'veg', true, 'drink', '1', '2 min', '8 min', 'A soothing caffeine-free brew of fresh ginger and tulsi with honey and lemon — ideal after dinner to aid digestion and ease into rest.', NULL, 'Traditional', NULL, ARRAY['Fresh ginger — 1 inch (sliced)','Tulsi leaves — 6 (fresh or dried)','Honey — 1 tsp','Fresh lemon juice — 1/2 tsp','Water — 1.5 cups']::text[], ARRAY['Bring water to a boil with ginger and tulsi leaves.','Reduce heat and simmer 5–7 minutes.','Strain into a mug.','Stir in honey and a squeeze of lemon. Sip warm.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'cup', 200, 20, 0.1, 5.2, 0.1, 0.1, 0.2, 8, 0, 2, false),
  (323, 'Tomato Chutney', 'South Indian', 'south_indian', 'vegan', false, 'chutney', '4', '5 min', '12 min', 'A tangy-spicy tomato relish cooked with onion, garlic and tamarind — robust enough to stand up to a crisp dosa or plain idli.', NULL, 'Traditional', NULL, ARRAY['Tomatoes — 3 medium (chopped)','Onion — 1 medium (chopped)','Garlic — 3 cloves','Dried red chillies — 2','Tamarind — a small piece','Oil — 2 tsp','Mustard seeds — 1/2 tsp','Curry leaves — 8','Salt — to taste','Asafoetida (hing) — a pinch']::text[], ARRAY['Heat oil in a pan. Add mustard seeds and let them splutter. Add asafoetida and curry leaves.','Add onion, garlic and dried red chillies. Saute until onion is golden, about 5 minutes.','Add chopped tomatoes, tamarind and salt. Cook on medium heat until tomatoes are completely mushy and oil separates, about 7 minutes.','Cool slightly. Blend to a coarse chutney. Serve at room temperature.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'tbsp', 40, 75, 1.2, 9.5, 2.8, 1.6, 0.8, 22, 0, 280, false),
  (324, 'Mint-Coriander Chutney', 'North Indian', 'north_indian', 'vegan', false, 'chutney', '6', '8 min', '0 min', 'A vivid green chutney of fresh mint and coriander with lemon and green chilli — the universal Indian dip that lifts every snack and meal.', NULL, 'Traditional', NULL, ARRAY['Fresh coriander leaves — 1 cup (packed)','Fresh mint leaves — 1/2 cup (packed)','Green chillies — 2','Garlic — 2 cloves','Fresh ginger — 1/2 inch','Fresh lemon juice — 1 tbsp','Salt — to taste','Water — 2 tbsp','Roasted cumin powder — 1/4 tsp']::text[], ARRAY['Add all ingredients to a blender: coriander, mint, green chillies, garlic, ginger, lemon juice, cumin, salt and water.','Blend until smooth, scraping down the sides as needed. Add a little more water if required.','Taste and adjust salt and lemon juice.','Transfer to an airtight container and refrigerate until needed. Best used the same day.']::text[], ARRAY['breakfast','lunch','dinner']::text[], 'tbsp', 30, 25, 0.8, 4.2, 0.3, 1.1, 1.2, 48, 0, 180, false),
  (325, 'Sambar', 'South Indian', 'south_indian', 'vegan', false, 'dal', '4', '15 min', '30 min', 'A South Indian lentil soup fragrant with tamarind, vegetables and sambar powder — the irreplaceable accompaniment to idli, dosa, and steamed rice.', NULL, 'Traditional', NULL, ARRAY['Toor dal — 1/2 cup','Tamarind — lemon-sized ball (soaked in 1 cup warm water)','Small shallots (sambar onions) — 6','Tomatoes — 2 (chopped)','Drumstick — 1 (cut into 2 inch pieces)','Sambar powder — 2 tsp','Turmeric powder — 1/4 tsp','Salt — to taste','Oil — 2 tsp','Mustard seeds — 1 tsp','Dried red chillies — 2','Curry leaves — 10','Asafoetida (hing) — 1/4 tsp']::text[], ARRAY['Pressure cook toor dal with turmeric and 1.5 cups water until completely soft (2–3 whistles). Mash well.','Extract tamarind juice by squeezing the soaked ball through the water; discard fibre.','In a pot, bring tamarind water to boil. Add shallots, tomatoes, drumstick and salt. Cook 10 minutes until vegetables are tender.','Add sambar powder and the mashed dal. Stir and simmer 10 more minutes. Adjust consistency with water.','In a small pan heat oil. Add mustard seeds — let splutter. Add dried red chillies, curry leaves and asafoetida. Pour tempering over sambar. Serve hot.']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'bowl', 150, 120, 4.2, 15.8, 2.1, 3.4, 2.8, 68, 0, 385, false),
  (326, 'Groundnut Chutney (Peanut Chutney)', 'South Indian', 'south_indian', 'vegan', false, 'chutney', '4', '5 min', '8 min', 'Roasted peanuts ground with garlic and chilli into a rich, nutty chutney — hearty, protein-rich and a bold alternative to coconut chutney.', NULL, 'Traditional', NULL, ARRAY['Roasted peanuts — 1/2 cup (skins removed)','Garlic — 2 cloves','Dried red chillies — 2','Tamarind — a small piece','Salt — to taste','Water — as needed','Oil — 1 tsp','Mustard seeds — 1/2 tsp','Curry leaves — 8','Asafoetida (hing) — a pinch']::text[], ARRAY['In a dry pan, lightly roast peanuts until fragrant if not already roasted. Cool.','Grind peanuts, garlic, red chillies, tamarind and salt with just enough water to a slightly coarse chutney — not too smooth.','Transfer to a bowl.','Heat oil, add mustard seeds and let them splutter. Add curry leaves and asafoetida. Pour tempering over chutney.','Mix and serve with idli, dosa or vada.']::text[], ARRAY['breakfast','lunch']::text[], 'tbsp', 40, 130, 5.2, 8.1, 8.9, 1.8, 1.4, 28, 0, 180, false),
  (327, 'Nannari Sarbath', 'South Indian', 'south_indian', 'vegan', true, 'drink', NULL, NULL, NULL, 'Refreshing Indian sarsaparilla syrup drink served chilled — cooling and aromatic.', NULL, 'Traditional', NULL, ARRAY['Nannari syrup 30 ml','Chilled water 200 ml','Lemon juice 1 tsp','Ice cubes']::text[], ARRAY['Mix nannari syrup with chilled water','Add lemon juice and stir','Serve over ice']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 230, 70, 0.1, 17.5, 0.1, 0.2, 0.3, 15, 0, 8, false),
  (328, 'Panakam', 'South Indian', 'south_indian', 'vegan', true, 'drink', NULL, NULL, NULL, 'Traditional South Indian jaggery drink spiced with cardamom and dry ginger.', NULL, 'Traditional', NULL, ARRAY['Jaggery 40 g','Water 200 ml','Cardamom powder 1/4 tsp','Dry ginger powder 1/4 tsp','Lemon juice 1 tsp']::text[], ARRAY['Dissolve jaggery in water','Add spices and lemon juice','Stir well and serve']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 220, 85, 0.1, 21.5, 0.1, 0.2, 0.8, 15, 0, 8, false),
  (329, 'Ragi Kanji (Finger Millet Porridge)', 'South Indian', 'south_indian', 'veg', true, 'drink', NULL, NULL, NULL, 'Nourishing finger millet porridge — a South Indian breakfast drink rich in iron and calcium.', NULL, 'Traditional', NULL, ARRAY['Ragi flour 3 tbsp','Water 300 ml','Salt to taste','Buttermilk 2 tbsp','Green chilli 1 (optional)']::text[], ARRAY['Mix ragi flour with a little water into a smooth paste','Boil remaining water; whisk in ragi paste','Cook on low heat 5 min stirring constantly','Add salt; serve warm']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'glass', 300, 120, 3.5, 22.8, 1.2, 2.1, 3.8, 65, 0.08, 185, false),
  (330, 'Idli Podi (Gun Powder Chutney)', 'South Indian', 'south_indian', 'vegan', true, 'podi', NULL, NULL, NULL, 'Spicy dry chutney powder of roasted lentils and chillies, served with sesame oil alongside idli and dosa.', NULL, 'Traditional', NULL, ARRAY['Urad dal 1/4 cup','Chana dal 1/4 cup','Dry red chillies 8','Sesame seeds 2 tbsp','Asafoetida 1/4 tsp','Salt to taste']::text[], ARRAY['Dry roast dals and chillies separately until golden','Cool completely','Grind coarsely with salt and asafoetida','Mix in sesame seeds','Serve with sesame oil']::text[], ARRAY['breakfast','lunch','dinner','snack']::text[], 'tbsp', 15, 80, 3.2, 6.8, 3.5, 1.2, 1.8, 45, 0.1, 180, false),
  (331, 'Lemon Rice (Chitranna)', 'South Indian', 'south_indian', 'vegan', true, 'main', NULL, NULL, NULL, 'Tangy South Indian rice tempered with mustard seeds, peanuts, and lemon juice — a beloved one-pot meal.', NULL, 'Traditional', NULL, ARRAY['Cooked rice 2 cups','Lemon juice 3 tbsp','Mustard seeds 1 tsp','Turmeric 1/2 tsp','Peanuts 2 tbsp','Curry leaves 10','Green chillies 2','Oil 2 tbsp','Salt to taste']::text[], ARRAY['Heat oil; splutter mustard seeds','Add peanuts, curry leaves, chillies; fry 1 min','Add turmeric and cooked rice','Mix in lemon juice and salt','Toss well and serve']::text[], ARRAY['lunch','dinner']::text[], 'plate', 250, 340, 6.8, 48.2, 12.5, 1.2, 1.8, 35, 0, 385, false),
  (332, 'Bisi Bele Bath', 'South Indian', 'south_indian', 'veg', false, 'main', NULL, NULL, NULL, 'Karnataka''s iconic one-pot comfort dish of rice, toor dal, vegetables, and warming spices.', NULL, 'Traditional', NULL, ARRAY['Rice 1 cup','Toor dal 1/2 cup','Mixed vegetables 1 cup','Tamarind paste 1 tbsp','Bisi bele bath powder 2 tsp','Ghee 2 tbsp','Mustard seeds 1 tsp','Cashews 10','Salt to taste']::text[], ARRAY['Pressure cook rice, dal, and vegetables together','Add tamarind paste and masala powder; simmer until thick','Prepare tempering with mustard seeds and cashews in ghee','Pour tempering over bath; serve hot']::text[], ARRAY['lunch','dinner']::text[], 'plate', 300, 380, 12.5, 52, 14.2, 8.5, 4.8, 95, 0.2, 380, false),
