  (336, 'Mango Achar (Pickle)', 'North Indian', 'north_indian', 'vegan', true, 'pickle', NULL, NULL, NULL, 'Pungent and spicy mango pickle — an indispensable condiment alongside parathas and dal.', NULL, 'Traditional', NULL, ARRAY['Mango pieces 100 g','Mustard oil 3 tbsp','Red chilli powder 1 tsp','Mustard seeds 1 tsp','Fenugreek seeds 1/2 tsp','Turmeric 1/4 tsp','Salt to taste']::text[], ARRAY['Mix spices with mustard oil','Toss mango pieces in spiced oil','Store in airtight jar','Serve as condiment']::text[], ARRAY['breakfast','lunch','dinner']::text[], 'tbsp', 15, 25, 0.8, 3.2, 1.1, 0.4, 0.3, 12, 0, 280, false),
  (337, 'Dahi (Fresh Curd)', 'Pan-Indian', 'pan_indian', 'veg', true, 'dairy', NULL, NULL, NULL, 'Plain set curd — the simplest and most essential accompaniment in Indian cooking. Eaten with rice, roti, or on its own at every meal.', 'Set curd at home by adding a teaspoon of live curd to warm (not hot) milk and leaving it undisturbed for 6–8 hours.', 'Staple', NULL, ARRAY['Full-fat milk 500 ml','Yogurt starter culture 2 tbsp']::text[], ARRAY['Boil milk and cool to lukewarm','Add starter culture and mix gently','Cover and leave undisturbed 6–8 hours','Refrigerate once set']::text[], ARRAY['breakfast','lunch','dinner']::text[], 'katori', 150, 100, 3.5, 5.2, 5.8, 0, 0.1, 180, 0.35, 65, false),
