  (345, 'Tandoori Roti', 'North Indian', 'north_indian', 'veg', true, 'staple', NULL, NULL, NULL, 'Whole-wheat flatbread baked in a tandoor or heavy skillet — soft inside with slightly charred edges.', NULL, 'Staple', NULL, ARRAY['Whole wheat flour 2 cups','Yogurt 2 tbsp','Water as needed','Salt 1/2 tsp','Butter to serve']::text[], ARRAY['Mix flour, yogurt, salt, and water into a soft dough; rest 30 min','Roll into thick circles','Cook on a very hot cast-iron pan or in oven at 230°C','Finish on flame until charred spots appear','Brush with butter']::text[], ARRAY['lunch','dinner']::text[], 'piece', 70, 150, 5.2, 27.8, 2.1, 4.2, 1.8, 28, 0.05, 285, false),
