-- ══════════════════════════════════════════════════
-- Phase 6b — Recipes, part 2 of 3 (181 recipes)
-- Run after phase6a. Safe to run more than once.
-- ══════════════════════════════════════════════════

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name, cuisine = EXCLUDED.cuisine, diet = EXCLUDED.diet, is_jain = EXCLUDED.is_jain, dish_type = EXCLUDED.dish_type,
  meal_hint = EXCLUDED.meal_hint, serving_unit = EXCLUDED.serving_unit, serving_weight_g = EXCLUDED.serving_weight_g,
  kcal = EXCLUDED.kcal, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, fibre_g = EXCLUDED.fibre_g,
  iron_mg = EXCLUDED.iron_mg, calcium_mg = EXCLUDED.calcium_mg, vit_b12_mcg = EXCLUDED.vit_b12_mcg, sodium_mg = EXCLUDED.sodium_mg,
  nutrition_estimated = EXCLUDED.nutrition_estimated;

-- Each recipe becomes a dish you can plan and log (nutrition stored per 100 g)
ON CONFLICT (recipe_id) DO UPDATE SET
  name = EXCLUDED.name, category = EXCLUDED.category, cuisine = EXCLUDED.cuisine, diet = EXCLUDED.diet, is_jain = EXCLUDED.is_jain,
  meal_hint = EXCLUDED.meal_hint, serving_unit = EXCLUDED.serving_unit, serving_weight_g = EXCLUDED.serving_weight_g,
  calories = EXCLUDED.calories, protein_g = EXCLUDED.protein_g, carbs_g = EXCLUDED.carbs_g, fat_g = EXCLUDED.fat_g, fiber_g = EXCLUDED.fiber_g,
  iron_mg = EXCLUDED.iron_mg, calcium_mg = EXCLUDED.calcium_mg, vitamin_b12_mcg = EXCLUDED.vitamin_b12_mcg, sodium_mg = EXCLUDED.sodium_mg,
  ingredients = EXCLUDED.ingredients, rasa = EXCLUDED.rasa, virya = EXCLUDED.virya,
  vata_effect = EXCLUDED.vata_effect, pitta_effect = EXCLUDED.pitta_effect, kapha_effect = EXCLUDED.kapha_effect;

-- Recipes that are the same dish as one already in the list: link them, no duplicate
UPDATE public.food_items f SET recipe_id = v.recipe_id
FROM (VALUES
  ('Murukku', 303),
  ('Tomato Chutney', 323),
  ('Sambar', 325),
  ('Uttapam', 286),
  ('Chapati / Roti', 299),
  ('Masala Chai (with milk)', 309),
  ('Filter Coffee (with milk)', 311),
  ('Buttermilk (thin)', 316),
  ('Coconut Water', 348)
) AS v(name, recipe_id)
WHERE f.name = v.name AND f.kutumbh_id IS NULL AND f.recipe_id IS NULL;

-- Check
SELECT (SELECT count(*) FROM public.recipes) AS recipes_so_far,
       (SELECT count(*) FROM public.food_items WHERE kutumbh_id IS NULL) AS dishes_in_list;
